window.QSBI_LESSONS=window.QSBI_LESSONS||{};QSBI_LESSONS[11]=[{"id":"11_19","g":11,"l":19,"topic":"Личный бренд: ключевые принципы","module":"Стратегический маркетинг","format":"Комбинированный","skills":["Работа с клиентом","Принятие решений","Критическое мышление"],"goal":"К концу урока ученик сможет сформулировать свои ценности, сильные стороны и позиционирование для личного бренда и оформить их в профиль «Я как бренд».","criteria":["Я называю свои ценности и сильные стороны и подтверждаю их примерами.","Я формулирую позиционирование: для кого я полезен и чем отличаюсь.","Я представляю профиль ясно и получаю обратную связь."],"result":"Профиль личного бренда: 3 ценности, 3 сильные стороны с доказательствами, формула позиционирования и визуальный набросок (цвета, символ).","stages":[{"stage":"Разминка «Правда или ловушка?»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Бренд (brand)","real":"Образ, который возникает у людей при упоминании имени, компании или продукта","shown":"Образ, который возникает у людей при упоминании имени, компании или продукта","truth":true,"first":"Б"},{"term":"Личный бренд","real":"То, как другие воспринимают человека: его ценности, навыки, репутацию","shown":"Короткая формула: кому я помогаю, чем и чем отличаюсь","truth":false,"first":"Л"},{"term":"Маркетинг (marketing) личного бренда","real":"Осознанное представление своих сильных сторон нужной аудитории","shown":"Осознанное представление своих сильных сторон нужной аудитории","truth":true,"first":"М"},{"term":"Ценности","real":"Убеждения, которые определяют поступки","shown":"То, как другие воспринимают человека: его ценности, навыки, репутацию","truth":false,"first":"Ц"},{"term":"Сильная сторона","real":"Навык или качество, в котором человек стабильно хорош","shown":"Навык или качество, в котором человек стабильно хорош","truth":true,"first":"С"},{"term":"Позиционирование","real":"Короткая формула: кому я помогаю, чем и чем отличаюсь","shown":"Убеждения, которые определяют поступки","truth":false,"first":"П"}],"perm":[3,2,1,0,5,4]},"glossary":[{"term":"Бренд (brand)","def":"Образ, который возникает у людей при упоминании имени, компании или продукта"},{"term":"Личный бренд","def":"То, как другие воспринимают человека: его ценности, навыки, репутацию"},{"term":"Маркетинг (marketing) личного бренда","def":"Осознанное представление своих сильных сторон нужной аудитории"},{"term":"Ценности","def":"Убеждения, которые определяют поступки"},{"term":"Сильная сторона","def":"Навык или качество, в котором человек стабильно хорош"},{"term":"Позиционирование","def":"Короткая формула: кому я помогаю, чем и чем отличаюсь"},{"term":"Цифровой след","def":"Информация о человеке, которая остаётся в интернете"}],"english":"brand — бренд; marketing — маркетинг","concepts":{"head":"Определения","items":["Бренд (brand) — это не логотип, а впечатление.","Личный бренд строится на ценностях, сильных сторонах и поступках; маркетинг (marketing) личного бренда — честное представление их людям."]},"steps":{"head":"Как это работает, по шагам","items":["Ценности — выбрать 3 из списка и вспомнить поступок, где они проявились","Сильные стороны — 3 навыка с доказательствами (проект, результат, отзыв)","Аудитория — кому это важно (колледж, работодатель, клиенты проекта)","Позиционирование по формуле «Я помогаю [кому] [что сделать] благодаря [сильная сторона], и отличаюсь [чем]»","Визуальный стиль — цвета и символ, отражающие ценности","Проверить цифровой след: соответствуют ли профили в соцсетях образу"]},"scheme":"«дом бренда»: фундамент — ценности, стены — сильные стороны с доказательствами, крыша — позиционирование, окна — визуальный стиль, двор — цифровой след.","examples":[{"lab":"Казахстанский","text":"Димаш Кудайберген —"},{"lab":"Пример сильного личного бренда","text":"Узнаваемый вокал, уважение к казахской культуре и к поклонникам, последовательность в образе."},{"lab":"Второй пример","text":"Условная ученица из Талдыкоргана: ценности — честность и забота; сильные стороны — дизайн, организация; позиционирование: «Помогаю школьным проектам выглядеть профессионально благодаря чувству стиля и организованности»."}],"mistake":{"myth":"Копировать чужой образ блогера","fix":"Бренд работает, только если он честный и опирается на реальные поступки."},"check":[{"q":"Чем бренд отличается от логотипа?","a":"Бренд — впечатление"},{"q":"Почему сильную сторону нужно подтверждать примером?","a":"Иначе это просто слова"},{"q":"Как цифровой след влияет на бренд?","a":"Работодатели и партнёры видят его"}],"kz":{"text":"Димаш Кудайберген — казахстанский певец с мировой аудиторией, чей личный бренд строится на уникальном голосе, уважении к национальной культуре и тесной связи с поклонниками.","link":"сильный личный бренд опирается на реальные сильные стороны и ценности."},"world":{"text":"Термин «личный бренд» популяризировал Том Питерс в статье «The Brand Called You» в журнале Fast Company (1997). Сегодня личный бренд важен для работы в международных командах и на фриланс-платформах.","link":""},"fact":"Статья Тома Питерса «The Brand Called You» вышла в Fast Company в 1997 году и стала одной из самых цитируемых в теме карьерного развития. В ней Питерс утверждал, что каждый человек — «генеральный директор компании Я».","cards":[{"n":"1","title":"Ценности и сильные стороны","lines":["Выберите 3 ценности из списка: честность, ответственность, забота, свобода, творчество, развитие, справедливость, дружба, трудолюбие, смелость, порядок, служение обществу.","Для каждой: поступок, где она проявилась.","Сильные стороны: 3 навыка + доказательство (проект, результат, отзыв)."],"hand":"Сдать: заполненную карточку.","answers":[]},{"n":"2","title":"Позиционирование и стиль","lines":["Формула: «Я помогаю ___ (кому) ___ (что сделать) благодаря ___ (сильная сторона), и отличаюсь ___».","Визуал: 2–3 цвета и почему; символ или знак.","Обратная связь партнёра: «Я вижу в тебе ___; формула понятна/непонятна, потому что ___»."],"hand":"Сдать: профиль «Я как бренд».","answers":[]}],"practice":[{"type":"case","title":"Деревенская кухня на весь мир","minutes":9,"source":"Ли Цзыци, китайский видеоблогер; рекорд Гиннесса за число подписчиков китайскоязычного канала YouTube, 2021","hook":"Без слов, без рекламы, без городских декораций. Почему её смотрят десятки миллионов?","story":["Ли Цзыци снимала видео о жизни в деревне в китайской провинции Сычуань: как она выращивает овощи, готовит, делает мебель и одежду по старинным технологиям.","В её видео почти нет разговоров, только красивая картинка, звуки природы и работа руками.","В 2021 году она попала в Книгу рекордов Гиннесса как автор китайскоязычного канала YouTube с самым большим числом подписчиков."],"question":"Какой принцип личного бренда здесь главный?","options":["Частая смена тем","Подлинность и постоянство: один узнаваемый стиль и ценности","Скандалы","Много рекламы"],"answerIndex":1,"reveal":"Её личный бренд — это постоянство: тот же стиль, те же ценности (природа, традиции, труд), узнаваемая подача. Аудитория верит, что это настоящее. Подлинность, постоянство и ценность для аудитории — ключевые принципы личного бренда.","teams":"Команды: сформулируйте для себя «позиционирование» по формуле: я — [кто] для [кого], который помогает [чем].","takeaway":"Личный бренд держится на подлинности и постоянстве."},{"type":"case","title":"Два кандидата на стажировку","minutes":8,"source":"Условная ситуация","hook":"Одинаковые оценки. Почему компания выбрала второго?","story":["На стажировку в маркетинговое агентство подали заявки два одиннадцатиклассника с одинаковыми оценками.","Профиль первого — случайные мемы и фото с отдыха.","У второго — серия постов «разбираю рекламу недели», 3 учебных проекта и отзывы клиентов с ярмарки."],"question":"Что сработало у второго кандидата?","options":["Знакомства","Больше подписчиков","Красивые фотографии","Личный бренд показал навыки и интерес к профессии на деле"],"answerIndex":3,"reveal":"Личный бренд — это доказательства: что ты делаешь, о чём думаешь, кто может тебя порекомендовать. Работодатель видит не слова «я креативный», а реальные работы.","teams":"Команды: составьте план личного бренда на 4 недели: 1 тема, 3 формата постов, 1 доказательство навыка.","takeaway":"Личный бренд — это доказательства, а не слова."}],"homework":"Проверь свой цифровой след (что видно о тебе публично) и составь список из 2 действий, которые сделают его ближе к твоему позиционированию.","support":"Список из 20 ценностей для выбора; шаблон формулы позиционирования с пропусками; вопросы-подсказки «где я помог другим?».","advanced":"Составить два варианта позиционирования для разных аудиторий (приёмная комиссия и клиент проекта) и объяснить разницу.","photo":{"src":"lessons/img/11_19.jpg","author":"Kane Reinholdtsen","q":["Что вы видите на фото? Как это связано с нашей темой?","Как личный бренд помогает найти работу или партнёров в другой стране?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g11-l19.pptx","name":"19. Личный бренд — ключевые принципы (11 кл).pptx","mb":1.5}},{"id":"11_20","g":11,"l":20,"topic":"Маркетинговая стратегия проекта: практикум","module":"Стратегический маркетинг","format":"Проектная мастерская","skills":["Финансовое мышление","Лидерство","Командная работа"],"goal":"К концу урока ученик сможет в команде собрать маркетинговую стратегию проекта на полгода: SMART-цели, целевую аудиторию, каналы, бюджет и показатели контроля.","criteria":["Мы формулируем SMART-цели и описываем целевую аудиторию.","Мы выбираем каналы и распределяем бюджет на полгода с обоснованием.","Мы задаём показатели контроля и защищаем стратегию."],"result":"Одностраничная маркетинговая стратегия проекта на 6 месяцев: цели, аудитория, позиционирование, каналы по месяцам, бюджет и KPI.","stages":[{"stage":"Разминка «Угадай слово»","min":4},{"stage":"Постановка задачи","min":4},{"stage":"Работа в командах","min":20},{"stage":"Промежуточный показ","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Маркетинг (marketing)","real":"Изучение клиентов и продвижение продукта","shown":"Изучение клиентов и продвижение продукта","truth":true,"first":"М"},{"term":"Стратегия (strategy)","real":"План достижения долгосрочных целей с выбором приоритетов","shown":"Ключевые показатели эффективности, по которым проверяют выполнение плана","truth":false,"first":"С"},{"term":"Проект (project)","real":"Работа с конкретным результатом и сроком","shown":"Работа с конкретным результатом и сроком","truth":true,"first":"П"},{"term":"Практика (practice)","real":"Применение знаний на реальной задаче","shown":"План достижения долгосрочных целей с выбором приоритетов","truth":false,"first":"П"},{"term":"Целевая аудитория","real":"Группа людей, для которых создан продукт","shown":"Группа людей, для которых создан продукт","truth":true,"first":"Ц"},{"term":"KPI","real":"Ключевые показатели эффективности, по которым проверяют выполнение плана","shown":"Применение знаний на реальной задаче","truth":false,"first":"K"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Маркетинг (marketing)","def":"Изучение клиентов и продвижение продукта"},{"term":"Стратегия (strategy)","def":"План достижения долгосрочных целей с выбором приоритетов"},{"term":"Проект (project)","def":"Работа с конкретным результатом и сроком"},{"term":"Практика (practice)","def":"Применение знаний на реальной задаче"},{"term":"Целевая аудитория","def":"Группа людей, для которых создан продукт"},{"term":"KPI","def":"Ключевые показатели эффективности, по которым проверяют выполнение плана"},{"term":"SMART-цель","def":"Конкретная, измеримая, достижимая, значимая, ограниченная сроком"}],"english":"marketing — маркетинг; project — проект; strategy — стратегия; practice — практика","concepts":{"head":"Определения","items":["Маркетинговая стратегия (strategy) проекта (project) — ответ на вопросы: кому продаём, что обещаем, где говорим, сколько тратим и как проверяем.","Практика (practice) урока — собрать стратегию на полгода для своего проекта."]},"steps":{"head":"Как это работает, по шагам","items":["SMART-цели (например, «200 продаж и 1 000 подписчиков к маю»)","Целевая аудитория — портрет: возраст, город, интересы, проблема","Позиционирование — чем мы лучше альтернатив","Каналы — 2–3 канала, где есть аудитория","Календарь по месяцам: запуск, рост, удержание","Бюджет по месяцам с опорой на CPA и маржу","KPI — охват, конверсия, CPA, ROMI — и контрольные точки"]},"scheme":"«дорожная карта» на 6 месяцев: три фазы «запуск — рост — удержание», под ними каналы и бюджет, справа колонка KPI.","examples":[{"lab":"Казахстанский","text":"Условный школьный проект «эко-сумки из Усть-Каменогорска»: цель 150 продаж за 6 месяцев; аудитория — студенты 16–22 лет; каналы — соцсеть, ярмарки, партнёрство с кофейнями; бюджет 180 000 условных тенге: 1–2 месяц — 60 000 на запуск, 3–6 — по 30 000. KPI: CPA не выше 1 200, конверсия ярмарки не ниже 10%."},{"lab":"Второй пример","text":"Стратегия без аудитории — «реклама для всех» — сжигает бюджет без продаж."}],"mistake":{"myth":"Стратегия как список «всё и везде»","fix":"Стратегия — это выбор, от чего мы отказываемся."},"check":[{"q":"Почему стратегия начинается с аудитории?","a":"Каналы и сообщения зависят от неё"},{"q":"Сколько каналов брать маленькому проекту?","a":"2–3, чтобы хватило ресурсов"},{"q":"Зачем KPI?","a":"Чтобы вовремя менять план"}],"kz":{"text":"Авиакомпания Air Astana с начала полётов в 2002 году последовательно строит бренд вокруг качества сервиса и казахстанского гостеприимства и получала международные награды за обслуживание.","link":"долгосрочная стратегия — это последовательность в позиционировании годами."},"world":{"text":"Компания Patagonia в 2011 году запустила кампанию «Don’t Buy This Jacket», призывая покупать меньше и чинить вещи; стратегия, связанная с ЦУР ООН 12, укрепила доверие к бренду.","link":""},"fact":"Кампания Patagonia «Don’t Buy This Jacket» вышла в виде рекламы в газете The New York Times в «Чёрную пятницу» 2011 года и стала одним из самых обсуждаемых примеров антипотребительского маркетинга.","cards":[{"n":"1","title":"Шаблон стратегии на 6 месяцев","lines":["1) SMART-цели (2): ___.","2) Портрет аудитории: возраст, город, интересы, проблема, где проводит время.","3) Позиционирование: «Для ___ наш ___ — это ___, в отличие от ___».","4) Каналы (2–3) и почему.","5) Календарь: месяцы 1–2 запуск, 3–4 рост, 5–6 удержание — действия.","6) Бюджет по месяцам (условные тенге), всего не более 200 000.","7) KPI и контрольные точки."],"hand":"Сдать: заполненную страницу.","answers":[]},{"n":"2","title":"Вопросы для защиты","lines":["1) Почему именно эта аудитория? 2) От каких каналов вы отказались и почему? 3) Какой KPI покажет, что пора менять план? 4) Окупается ли бюджет при вашей марже?"],"hand":"Сдать: лист взаимооценки с ответами команды.","answers":[]}],"practice":[{"type":"case","title":"Blockbuster и Netflix","minutes":10,"source":"Netflix и Blockbuster, 2000–2010","hook":"Netflix предложил себя гиганту проката за 50 миллионов долларов. Гигант отказался.","story":["В 2000 году Netflix был небольшой компанией, которая отправляла DVD по почте. Основатели предложили Blockbuster — крупнейшей сети видеопроката — купить их за 50 миллионов долларов.","Руководство Blockbuster отказалось: у них были тысячи магазинов и огромная прибыль, в том числе от штрафов за просрочку.","Netflix сделал стратегию на подписку без штрафов, а потом — на онлайн-стриминг."],"question":"Что, по-вашему, случилось с Blockbuster?","options":["Купил Netflix позже","Обанкротился в 2010 году, а Netflix стал мировым гигантом","Остался лидером","Перешёл в стриминг первым"],"answerIndex":1,"reveal":"Blockbuster объявил о банкротстве в 2010 году. Его стратегия держалась на старой модели, а Netflix менял стратегию вслед за клиентом и технологиями. Маркетинговая стратегия — это выбор: для кого, какая ценность, через какие каналы.","teams":"Команды: составьте маркетинговую стратегию своего проекта: сегмент, ценность, каналы, цена, метрика успеха.","takeaway":"Стратегия следует за клиентом, а не за привычкой."},{"type":"case","title":"Сова, которая грозит","minutes":8,"source":"Маркетинг Duolingo в соцсетях: зелёная сова Duo","hook":"Приложение для изучения языков стало звездой TikTok. Как?","story":["Duolingo — приложение для изучения языков. Его маскот — зелёная сова Duo, известная «угрожающими» напоминаниями заниматься.","Компания начала вести TikTok в странном и смешном стиле: ростовая кукла совы танцует, шутит над трендами и над самой собой.","Аккаунт набрал миллионы подписчиков."],"question":"Какой выбор стратегии здесь главный?","options":["Платная реклама на ТВ","Серьёзные уроки в TikTok","Говорить с молодой аудиторией на её языке и с юмором, через живого персонажа","Скидки"],"answerIndex":2,"reveal":"Duolingo выбрал аудиторию (молодёжь), канал (TikTok) и тон (самоирония через персонажа). Стратегия совпала с образом бренда — «назойливой» совы из уведомлений.","teams":"Команды: выберите для проекта один канал и тон общения. Придумайте 3 идеи коротких видео.","takeaway":"Стратегия = аудитория + канал + тон, согласованные с брендом."}],"homework":"Доработайте стратегию по отзывам, проверьте портрет аудитории опросом 5 человек из неё и скорректируйте каналы.","support":"Заполненный образец стратегии «эко-сумки»; шаблон с подсказками в каждом блоке.","advanced":"Добавить в стратегию план «Б» на случай, если главный канал не даст KPI за первые 2 месяца.","photo":{"src":"lessons/img/11_20.jpg","author":"Kaleidico","q":["Что вы видите на фото? Как это связано с нашей темой?","Может ли честная экологичная позиция быть частью маркетинговой стратегии малого проекта?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g11-l20.pptx","name":"20. Маркетинговая стратегия проекта — практикум (11 кл).pptx","mb":1.4}},{"id":"11_21","g":11,"l":21,"topic":"Как устроены нейросети и большие языковые модели","module":"Искусственный интеллект","format":"Комбинированный","skills":["Критическое мышление","Принятие решений"],"goal":"К концу урока ученик сможет объяснить, как языковая модель предсказывает следующий фрагмент текста, и назвать 3 причины, по которым она может ошибаться.","criteria":["Я объясняю своими словами, как языковая модель строит ответ по вероятностям.","Я называю 3 причины ошибок ИИ и показываю их на примерах.","Я связываю устройство ИИ с бизнес-моделью компаний и с тем, как проверять ответы."],"result":"Схема-объяснение «Как думает языковая модель» с примером предсказания и разобранными 3 ошибками ИИ из реальных ответов.","stages":[{"stage":"Разминка «Найди пару»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Искусственный интеллект (artificial intelligence)","real":"Программы, которые решают задачи, обычно требующие человеческого мышления","shown":"Программы, которые решают задачи, обычно требующие человеческого мышления","truth":true,"first":"И"},{"term":"Нейросеть","real":"Математическая модель из множества связанных «нейронов», которая учится находить закономерности в данных","shown":"Уверенный, но неверный или выдуманный ответ ИИ","truth":false,"first":"Н"},{"term":"Большая языковая модель (LLM)","real":"Нейросеть, обученная на огромных объёмах текста предсказывать следующий фрагмент текста","shown":"Нейросеть, обученная на огромных объёмах текста предсказывать следующий фрагмент текста","truth":true,"first":"Б"},{"term":"Токен","real":"Кусочек текста (слово или часть слова), с которым работает модель","shown":"Математическая модель из множества связанных «нейронов», которая учится находить закономерности в данных","truth":false,"first":"Т"},{"term":"Обучение модели","real":"Настройка параметров нейросети на примерах","shown":"Настройка параметров нейросети на примерах","truth":true,"first":"О"},{"term":"Галлюцинация","real":"Уверенный, но неверный или выдуманный ответ ИИ","shown":"Кусочек текста (слово или часть слова), с которым работает модель","truth":false,"first":"Г"}],"perm":[1,0,5,4,3,2]},"glossary":[{"term":"Искусственный интеллект (artificial intelligence)","def":"Программы, которые решают задачи, обычно требующие человеческого мышления"},{"term":"Нейросеть","def":"Математическая модель из множества связанных «нейронов», которая учится находить закономерности в данных"},{"term":"Большая языковая модель (LLM)","def":"Нейросеть, обученная на огромных объёмах текста предсказывать следующий фрагмент текста"},{"term":"Токен","def":"Кусочек текста (слово или часть слова), с которым работает модель"},{"term":"Обучение модели","def":"Настройка параметров нейросети на примерах"},{"term":"Галлюцинация","def":"Уверенный, но неверный или выдуманный ответ ИИ"},{"term":"Бизнес-модель (business model)","def":"Способ, которым компания создаёт ценность и зарабатывает"}],"english":"business model — бизнес-модель; artificial intelligence — искусственный интеллект","concepts":{"head":"Определения","items":["Искусственный интеллект (artificial intelligence) — широкий класс программ.","Большая языковая модель — нейросеть, которая на огромном объёме текстов научилась предсказывать, какой токен (кусочек слова) вероятнее всего идёт дальше."]},"steps":{"head":"Как это работает, по шагам","items":["Текст запроса разбивается на токены","Модель оценивает вероятности возможных следующих токенов, учитывая весь контекст","Выбирает один из вероятных токенов и добавляет к тексту","Повторяет, пока ответ не готов. Модель не «ищет в базе», а продолжает текст по выученным закономерностям. Поэтому она ошибается: а) данные устарели (модель обучена до определённой даты); б) в обучающих данных были ошибки или мало информации по теме; в) вероятное продолжение не обязательно правдиво — так появляются галлюцинации, например выдуманные источники"]},"scheme":"«Мама мыла …» → три стрелки с вероятностями: «раму» 0,6; «посуду» 0,3; «кота» 0,1. Ниже конвейер «запрос → токены → вероятности → выбор → ответ» и три «ловушки».","examples":[{"lab":"Казахстанский","text":"В Казахстане в Назарбаев Университете (институт ISSAI) разработали языковую модель KazLLM, чтобы ИИ лучше понимал казахский язык: моделям, обученным в основном на английском, данных на казахском не хватает."},{"lab":"Второй пример","text":"На вопрос «Какая ставка НДС в Казахстане?» модель с устаревшими данными может уверенно назвать старое значение — причина а)."}],"mistake":{"myth":"«Если ИИ ответил уверенно, значит правда»","fix":"Уверенный тон — свойство текста, а не гарантия факта."},"check":[{"q":"Знает ли модель факты как энциклопедия?","a":"Нет, она предсказывает текст"},{"q":"Почему ИИ может выдумать источник?","a":"Ссылка «похожа» на правдоподобный текст"},{"q":"Как компании зарабатывают на ИИ?","a":"Подписки, оплата за использование API, корпоративные решения"}],"kz":{"text":"Институт интеллектуальных и умных систем (ISSAI) Назарбаев Университета разработал KazLLM — языковую модель с поддержкой казахского языка.","link":"качество модели зависит от данных, на которых она обучена, и для казахского языка нужны свои данные."},"world":{"text":"Архитектура «трансформер», на которой построены современные языковые модели, описана в статье исследователей Google «Attention Is All You Need» (2017). Сегодня ИИ влияет на рынок труда во всём мире, что связано с ЦУР ООН 8 и 9.","link":""},"fact":"Сервис ChatGPT компании OpenAI, запущенный 30 ноября 2022 года, по оценке аналитиков UBS набрал около 100 миллионов пользователей примерно за два месяца — тогда это был один из самых быстрых ростов среди потребительских приложений.","cards":[{"n":"1","title":"Я — языковая модель","lines":["Партнёр читает начало фразы, вы называете 3 варианта продолжения и «вероятности» (в сумме 1):","1) «Казахстан — самая большая по площади страна в …»","2) «Чтобы открыть ИП, нужно …»","3) «Лучший способ сэкономить деньги — …»","Вопрос: в какой фразе самое вероятное продолжение не обязательно правильное?"],"hand":"Сдать: таблицу вариантов.","answers":[]},{"n":"2","title":"Поймай ошибку ИИ","lines":["Задайте ассистенту: А) вопрос о свежем событии этого месяца; Б) вопрос о малоизвестном факте вашего города; В) «Дай 3 научных источника о …» по теме проекта.","Для каждого ответа: верно/неверно; как проверили; причина ошибки (устаревшие данные / мало данных / галлюцинация)."],"hand":"Сдать: таблицу проверки.","answers":[]}],"practice":[{"type":"case","title":"Ход 37","minutes":10,"source":"Матч AlphaGo (DeepMind) против Ли Седоля, Сеул, март 2016","hook":"Нейросеть сделала ход, который комментаторы сочли ошибкой. А потом выиграла.","story":["В 2016 году программа AlphaGo компании DeepMind сыграла пять партий в го против одного из лучших игроков мира — Ли Седоля.","Во второй партии AlphaGo сделала 37-й ход, который профессионалы сначала приняли за ошибку: так люди не играли.","AlphaGo училась на миллионах позиций и затем играла сама с собой."],"question":"Что, по-вашему, показал «ход 37»?","options":["Ли Седоль ошибся","Программа случайно угадала","Нейросеть находит закономерности в данных, которые люди не замечают","Компьютер умеет думать как человек"],"answerIndex":2,"reveal":"AlphaGo выиграла матч 4:1. Нейросеть не «думает», как человек: она обучается на огромных данных и находит закономерности. Большие языковые модели работают похоже: учатся на огромном количестве текста и предсказывают следующее слово.","teams":"Команды: сыграйте в «языковую модель»: продолжите фразу «Ярмарка в школе прошла…» тремя самыми вероятными словами. Почему именно ими?","takeaway":"Нейросеть учится на данных и находит закономерности."},{"type":"case","title":"Модель, которая уверенно ошибается","minutes":8,"source":"Условная ситуация","hook":"Языковая модель уверенно назвала дату события, которого не было. Почему так бывает?","story":["Ученик спросил ИИ-ассистента: «Когда в Актобе открыли первый бизнес-инкубатор?».","Ассистент уверенно назвал год и название, но таких данных не оказалось нигде.","Ученик был уверен: «Раз компьютер — значит точно»."],"question":"Почему языковая модель может придумать ответ?","options":["Она специально обманывает","Так не бывает","Она предсказывает правдоподобный текст, а не проверяет факты","У неё сломался интернет"],"answerIndex":2,"reveal":"Языковые модели генерируют вероятный текст. Если данных мало, они могут «додумать» правдоподобный, но неверный ответ — это называют галлюцинацией. Поэтому факты нужно проверять по источникам.","teams":"Команды: придумайте 3 вопроса, на которые ИИ скорее ответит точно, и 3 — где высок риск ошибки.","takeaway":"Модель предсказывает слова — факты проверяем сами."}],"homework":"Напиши объяснение «Как работает языковая модель» для ученика 6 класса (100–150 слов) и приведи 1 пример ошибки ИИ, которую ты сам проверил.","support":"Схема-конвейер с пропусками; список 3 причин ошибок с примерами-подсказками.","advanced":"Объяснить, почему модель может дать разные ответы на один и тот же вопрос (выбор среди вероятных токенов), и показать это на практике.","photo":{"src":"lessons/img/11_21.jpg","author":"Growtika","q":["Что вы видите на фото? Как это связано с нашей темой?","Какие навыки останутся важными для людей, если ИИ хорошо пишет тексты?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g11-l21.pptx","name":"21. Как устроены нейросети и большие языковые модели (11 кл).pptx","mb":1.4}},{"id":"11_22","g":11,"l":22,"topic":"ИИ в бизнесе и маркетинге: что умеют нейросети","module":"Искусственный интеллект","format":"Комбинированный","skills":["Работа с клиентом","Критическое мышление"],"goal":"К концу урока ученик сможет назвать 5 задач маркетинга, которые решает ИИ, и 3 ограничения ИИ, приводя примеры из бизнеса.","criteria":["Я называю 5 задач маркетинга, где помогает ИИ, с примерами.","Я называю 3 ограничения ИИ и как их учесть.","Я оцениваю, где решение должен принимать человек, особенно в работе с клиентом."],"result":"Карта «ИИ в маркетинге»: 5 задач с примером инструмента и пользы для бизнеса, 3 ограничения и правило проверки для каждого.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Бизнес (business)","real":"Деятельность ради прибыли через решение проблем клиентов","shown":"Деятельность ради прибыли через решение проблем клиентов","truth":true,"first":"Б"},{"term":"Маркетинг (marketing)","real":"Изучение клиентов и продвижение продукта","shown":"Программа, отвечающая клиентам в переписке","truth":false,"first":"М"},{"term":"Искусственный интеллект (artificial intelligence)","real":"Программы, решающие задачи, требующие мышления","shown":"Программы, решающие задачи, требующие мышления","truth":true,"first":"И"},{"term":"Генеративный ИИ","real":"ИИ, создающий новый контент: тексты, изображения, видео","shown":"Изучение клиентов и продвижение продукта","truth":false,"first":"Г"},{"term":"Рекомендательная система","real":"Алгоритм, предлагающий клиенту товары по его поведению","shown":"Алгоритм, предлагающий клиенту товары по его поведению","truth":true,"first":"Р"},{"term":"Чат-бот","real":"Программа, отвечающая клиентам в переписке","shown":"ИИ, создающий новый контент: тексты, изображения, видео","truth":false,"first":"Ч"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Бизнес (business)","def":"Деятельность ради прибыли через решение проблем клиентов"},{"term":"Маркетинг (marketing)","def":"Изучение клиентов и продвижение продукта"},{"term":"Искусственный интеллект (artificial intelligence)","def":"Программы, решающие задачи, требующие мышления"},{"term":"Генеративный ИИ","def":"ИИ, создающий новый контент: тексты, изображения, видео"},{"term":"Рекомендательная система","def":"Алгоритм, предлагающий клиенту товары по его поведению"},{"term":"Чат-бот","def":"Программа, отвечающая клиентам в переписке"},{"term":"Предвзятость данных","def":"Искажения в данных, из-за которых ИИ делает несправедливые выводы"}],"english":"business — бизнес; marketing — маркетинг; artificial intelligence — искусственный интеллект","concepts":{"head":"Определения","items":["ИИ в маркетинге (marketing) — инструменты, которые ускоряют работу и помогают понять клиента.","Бизнес (business) использует искусственный интеллект (artificial intelligence), чтобы экономить время и повышать продажи."]},"steps":{"head":"Как это работает","items":["Пять задач: 1 — создание контента (тексты постов, варианты картинок); 2 — персональные рекомендации (что купить дальше); 3 — анализ отзывов и настроения клиентов; 4 — сегментация аудитории по поведению; 5 — чат-боты для ответов 24/7 и прогноз спроса. Три ограничения","Ошибки и галлюцинации — нужно проверять факты","Предвзятость и устаревшие данные — выводы могут быть несправедливыми","Риски авторского права и персональных данных — нельзя загружать данные клиентов в открытые сервисы, нужно проверять права на изображения. Порядок работы: задача → ИИ-черновик → проверка человеком → решение"]},"scheme":"«звезда» с 5 лучами-задачами; под ней «стоп-знак» с 3 ограничениями; внизу цепочка «ИИ — черновик, человек — решение».","examples":[{"lab":"Казахстанский","text":"Крупные маркетплейсы и сервисы доставки в Казахстане показывают покупателям персональные рекомендации товаров на основе их покупок — это задача 2."},{"lab":"Второй пример","text":"Условная кофейня в Шымкенте загрузила 200 отзывов в ИИ и узнала, что чаще всего жалуются на долгое ожидание, а не на вкус, — задача 3; решение (добавить бариста) принимает владелец."}],"mistake":{"myth":"«ИИ заменит маркетолога полностью»","fix":"ИИ ускоряет, но стратегию, этику и ответственность несёт человек."},"check":[{"q":"Какая задача ИИ ближе всего к работе с клиентом?","a":"Чат-бот, рекомендации"},{"q":"Почему нельзя загружать базу клиентов в открытый чат-бот?","a":"Персональные данные"},{"q":"Кто отвечает за пост, написанный ИИ?","a":"Бренд и человек, опубликовавший его"}],"kz":{"text":"Kaspi.kz — пример казахстанской цифровой экосистемы, где данные о покупках и платежах помогают предлагать клиентам товары и сервисы в одном приложении.","link":"персонализация — одна из главных задач ИИ в маркетинге."},"world":{"text":"Netflix использует рекомендательные алгоритмы, и в 2006–2009 годах компания провела конкурс Netflix Prize с призом 1 миллион долларов за улучшение рекомендаций на 10%. В ЕС в 2024 году принят Закон об ИИ (AI Act), регулирующий риски.","link":""},"fact":"Конкурс Netflix Prize (2006–2009) выиграла международная команда BellKor’s Pragmatic Chaos, улучшив алгоритм рекомендаций более чем на 10% и получив 1 миллион долларов.","cards":[{"n":"1","title":"Задача для группы","lines":["Выберите одну:","А) Пост: попросите ИИ написать пост о новинке проекта для аудитории 16–20 лет; проверьте факты и тон.","Б) Отзывы: дайте ИИ 10 отзывов: «долго ждать», «вкусно», «дорого», «вкусно, но долго», «персонал вежливый», «долго», «цена норм», «шумно», «быстро сегодня», «очень долго». Попросите выделить главные темы и проверьте подсчёт вручную.","В) Сегменты: попросите ИИ предложить 3 сегмента клиентов проекта и оцените логику."],"hand":"Сдать: результат и список правок.","answers":[]},{"n":"2","title":"Кейсы ограничений","lines":["1) ИИ написал пост с «фактом», которого нет.","2) Рекламный алгоритм почти не показывает рекламу одной из групп клиентов.","3) Сотрудник загрузил в открытый чат-бот таблицу с телефонами клиентов.","Задание: определите ограничение и правило, которое бы предотвратило ошибку."],"hand":"Сдать: таблицу «кейс — ограничение — правило».","answers":[]}],"practice":[{"type":"case","title":"Чат-бот вместо 700 операторов","minutes":9,"source":"Klarna, ИИ-ассистент поддержки клиентов, 2024–2025 (по заявлениям компании)","hook":"Компания заявила, что ИИ делает работу сотен людей. Что было дальше?","story":["В 2024 году шведская платёжная компания Klarna объявила, что её ИИ-ассистент за первый месяц провёл около двух третей всех чатов поддержки.","По заявлению компании, это была работа примерно 700 операторов.","Однако в 2025 году руководство признало, что качество общения важно, и снова стало нанимать людей в поддержку."],"question":"Какой вывод для бизнеса из этой истории?","options":["Поддержка клиентов не нужна","ИИ полностью заменяет людей","ИИ хорошо справляется с типовыми задачами, но людям остаются сложные и важные случаи","ИИ бесполезен"],"answerIndex":2,"reveal":"ИИ быстро отвечает на типовые вопросы, но клиенты ценят человеческое общение в сложных ситуациях. Лучший результат — сочетание: ИИ делает рутину, люди решают сложное.","teams":"Команды: выберите 3 задачи вашего проекта, которые можно отдать ИИ, и 2, которые должен делать человек.","takeaway":"ИИ берёт рутину, человек — сложное и важное."},{"type":"case","title":"ИИ для школьной кофейни","minutes":8,"source":"Условная ситуация","hook":"У школьной кофейни 3 задачи. Где нейросеть поможет, а где нет?","story":["Задача 1: придумать 10 вариантов названия нового напитка.","Задача 2: решить, сколько стаканов закупить на завтра, по продажам за месяц.","Задача 3: приготовить напиток и улыбнуться покупателю."],"question":"Где ИИ поможет меньше всего?","options":["Задача 2 — анализ продаж","Везде одинаково","Задача 1 — идеи названий","Задача 3 — живое обслуживание"],"answerIndex":3,"reveal":"Генеративный ИИ хорош для идей и текстов (задача 1), аналитика — для прогнозов по данным (задача 2). Живое обслуживание и вкус остаются за людьми.","teams":"Команды: составьте таблицу «задача — какой ИИ — что проверяет человек» для своего проекта.","takeaway":"Нейросети — инструмент под конкретную задачу."}],"homework":"Выбери одну задачу маркетинга своего проекта, реши её с ИИ и опиши в таблице: запрос, результат, что исправил сам, какой риск учёл.","support":"Список 5 задач с примерами инструментов; готовые 10 условных отзывов для анализа.","advanced":"Составить «правила использования ИИ» для маркетинга своего проекта из 5 пунктов.","photo":{"src":"lessons/img/11_22.jpg","author":"Glenn Carstens-Peters","q":["Что вы видите на фото? Как это связано с нашей темой?","Где проходит граница между удобной рекомендацией и манипуляцией выбором?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g11-l22.pptx","name":"22. ИИ в бизнесе и маркетинге — что умеют нейросети (11 кл).pptx","mb":1.3}},{"id":"11_23","g":11,"l":23,"topic":"Ярмарка: упаковка и фирменный стиль","module":"Стратегический маркетинг","format":"Симуляция, ярмарка","skills":["Работа с клиентом","Принятие решений","Финансовое мышление"],"goal":"К концу урока ученик сможет разработать и применить на ярмарке упаковку и элементы фирменного стиля продукта и оценить их влияние на продажи по цифрам.","criteria":["Я создаю упаковку и фирменный стиль, которые соответствуют позиционированию продукта.","Я выполняю свою роль на ярмарке и веду учёт продаж и реакций покупателей.","Я делаю вывод, как стиль повлиял на продажи, с опорой на цифры."],"result":"Упаковка и мини-брендбук продукта для ярмарки (логотип, цвета, шрифт, слоган) и учёт продаж с отметкой реакции покупателей на упаковку.","stages":[{"stage":"Разминка «Угадай слово»","min":4},{"stage":"Подготовка","min":6},{"stage":"Ярмарка","min":18},{"stage":"Подсчёт","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Ярмарка (fair)","real":"Учебная торговая площадка с условными тенге","shown":"Учебная торговая площадка с условными тенге","truth":true,"first":"Я"},{"term":"Компания (company)","real":"Организация, ведущая бизнес; на ярмарке — команда проекта","shown":"Оболочка продукта, которая защищает его и «продаёт» на полке","truth":false,"first":"К"},{"term":"Маркетинг (marketing)","real":"Изучение клиентов и продвижение продукта","shown":"Изучение клиентов и продвижение продукта","truth":true,"first":"М"},{"term":"Фирменный стиль","real":"Единый набор логотипа, цветов, шрифтов и образов бренда","shown":"Организация, ведущая бизнес; на ярмарке — команда проекта","truth":false,"first":"Ф"},{"term":"Брендбук","real":"Документ с правилами использования фирменного стиля","shown":"Документ с правилами использования фирменного стиля","truth":true,"first":"Б"},{"term":"Упаковка","real":"Оболочка продукта, которая защищает его и «продаёт» на полке","shown":"Единый набор логотипа, цветов, шрифтов и образов бренда","truth":false,"first":"У"}],"perm":[3,2,1,0,5,4]},"glossary":[{"term":"Ярмарка (fair)","def":"Учебная торговая площадка с условными тенге"},{"term":"Компания (company)","def":"Организация, ведущая бизнес; на ярмарке — команда проекта"},{"term":"Маркетинг (marketing)","def":"Изучение клиентов и продвижение продукта"},{"term":"Фирменный стиль","def":"Единый набор логотипа, цветов, шрифтов и образов бренда"},{"term":"Брендбук","def":"Документ с правилами использования фирменного стиля"},{"term":"Упаковка","def":"Оболочка продукта, которая защищает его и «продаёт» на полке"},{"term":"Себестоимость упаковки","def":"Затраты на упаковку одной единицы товара"}],"english":"fair — ярмарка; company — компания; marketing — маркетинг","concepts":{"head":"Определения","items":["Фирменный стиль компании (company) — это «лицо» бренда: логотип, 2–3 цвета, шрифт, слоган.","Упаковка — первая точка контакта с покупателем на ярмарке (fair): за 3–5 секунд она должна сказать, что это, для кого и почему стоит купить.","Маркетинг (marketing) проверяет это цифрами продаж."]},"steps":{"head":"Как это работает, по шагам","items":["Позиционирование одной фразой","Цвета под эмоцию (зелёный — эко, чёрный — премиум, яркие — молодёжь)","Логотип — простой, читаемый на расстоянии","Упаковка: название, польза, цена, контакт, честная информация о составе","Себестоимость упаковки — включаем в цену","На ярмарке отмечаем: подошёл ли покупатель из-за упаковки, купил ли","Считаем конверсию: покупки ÷ подошедшие"]},"scheme":"«правило 3 секунд»: что? для кого? почему купить?; рядом мини-брендбук: логотип, 3 цвета, шрифт, слоган.","examples":[{"lab":"Казахстанский","text":"Кондитерская фабрика «Рахат» (основана в 1942 году в Алматы) десятилетиями узнаётся по фирменной упаковке и национальным мотивам на коробках конфет."},{"lab":"Второй пример","text":"Команда из Актобе продавала печенье в простых пакетах: подошли 30, купили 6 (20%). Во втором часе — крафт-пакет с логотипом и наклейкой «домашнее, без консервантов»: подошли 35, купили 14 (40%). Упаковка стоила 50 условных тенге за штуку, цену подняли с 300 до 350, и прибыль выросла."}],"mistake":{"myth":"Перегрузить упаковку деталями и мелким текстом","fix":"Читаемость важнее красоты."},"check":[{"q":"Зачем единый стиль на всех материалах?","a":"Узнаваемость"},{"q":"Включать ли упаковку в себестоимость?","a":"Да"},{"q":"Как понять, что упаковка работает?","a":"По конверсии"}],"kz":{"text":"Кондитерская фабрика «Рахат» в Алматы, основанная в 1942 году, — один из самых узнаваемых казахстанских брендов, чья упаковка с национальными орнаментами стала частью образа страны и популярным подарком.","link":"фирменный стиль работает десятилетиями."},"world":{"text":"Мировая проблема упаковочных отходов привела к движению за экологичную упаковку: многие страны вводят ограничения на одноразовый пластик. Это связано с ЦУР ООН 12 «Ответственное потребление и производство» и ЦУР 14.","link":""},"fact":"Знак Nike — «свуш» — в 1971 году нарисовала студентка Кэролин Дэвидсон за 35 долларов; позже компания подарила ей акции. Сегодня это один из самых узнаваемых логотипов мира.","cards":[{"n":"1","title":"Мини-брендбук и упаковка","lines":["Позиционирование: «___ для ___, потому что ___».","Логотип (набросок), 2–3 цвета и почему, шрифт, слоган до 5 слов.","Упаковка: название, польза, цена, честная информация о составе.","Себестоимость упаковки за штуку ___; себестоимость товара ___; цена ___."],"hand":"Сдать: брендбук и образец упаковки.","answers":[]},{"n":"2","title":"События ярмарки и журнал","lines":["Событие 1: «Покупатели ищут подарки: 3 минуты лучше продаётся то, что красиво упаковано».","Событие 2: «Эко-проверка: команды с пластиковой упаковкой платят „эко-сбор“ 200 тенге».","Журнал: Время | Подошёл | Купил | Что привлекло (упаковка / цена / продавец)."],"hand":"Сдать: журнал и итог конверсии.","answers":[]}],"practice":[{"type":"case","title":"Коробочка цвета Tiffany","minutes":9,"source":"Фирменный цвет Tiffany Blue, компания Tiffany & Co.","hook":"Цвет коробки настолько узнаваем, что его зарегистрировали как товарный знак.","story":["Ювелирная компания Tiffany & Co. с XIX века использует один и тот же оттенок голубого.","Этот цвет есть на коробках, пакетах, каталогах и сайте.","Компания зарегистрировала цвет как товарный знак, а сам оттенок закреплён в каталоге Pantone под отдельным номером."],"question":"Почему, по-вашему, компания так бережёт один цвет?","options":["Голубой — самый дешёвый цвет","Фирменный стиль делает бренд узнаваемым ещё до того, как увидят товар","Это случайность","Так требует закон"],"answerIndex":1,"reveal":"Голубую коробку узнают сразу, и она сама стала символом подарка. Фирменный стиль — цвет, шрифт, упаковка — работает, когда его повторяют везде одинаково.","teams":"Команды: выберите для своего товара 1 фирменный цвет, 1 шрифт и 1 элемент упаковки. Проверьте: узнают ли вас без логотипа?","takeaway":"Фирменный стиль работает через повторение."},{"type":"case","title":"Бутылка, которую узнают на ощупь","minutes":8,"source":"Контурная бутылка Coca-Cola, 1915","hook":"Задача для стеклодувов: бутылку должны узнать в темноте и даже разбитой.","story":["В начале XX века у Coca-Cola было много подражателей с похожими названиями.","В 1915 году компания объявила конкурс на бутылку, которую можно узнать на ощупь в темноте и даже по осколку.","Победила фигурная бутылка с изгибами и рёбрами."],"question":"Зачем бренду упаковка, которую узнают на ощупь?","options":["Так было дешевле","Чтобы сэкономить стекло","Чтобы бутылка не скользила","Чтобы отличаться от подделок и запоминаться"],"answerIndex":3,"reveal":"Упаковка стала частью бренда, и форму бутылки позже тоже зарегистрировали как товарный знак. Упаковка защищает от подражателей и запоминается.","teams":"Команды: придумайте элемент упаковки вашего ярмарочного товара, который нельзя спутать с другими.","takeaway":"Упаковка — часть бренда, а не просто обёртка."}],"homework":"Оформи мини-брендбук проекта на 1 странице (логотип, цвета, шрифт, слоган, правило использования) и напиши, что изменишь в упаковке по итогам ярмарки.","support":"Шаблон брендбука; палитры-образцы; трафарет для логотипа.","advanced":"Сделать два варианта упаковки и провести на ярмарке A/B-тест с подсчётом конверсии каждого.","photo":{"src":"lessons/img/11_23.jpg","author":"Nguyễn Đức","q":["Что вы видите на фото? Как это связано с нашей темой?","Как сделать упаковку привлекательной и при этом экологичной?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g11-l23.pptx","name":"23. Ярмарка — упаковка и фирменный стиль (11 кл).pptx","mb":1.7}},{"id":"11_24","g":11,"l":24,"topic":"Промпт для ИИ: практикум на задаче своего проекта","module":"Искусственный интеллект","format":"Проектная мастерская","skills":["Командная работа","Креативность","Критическое мышление"],"goal":"К концу урока ученик сможет написать запрос к ИИ по схеме «роль, задача, контекст, формат» для задачи своего проекта и улучшить его минимум дважды по результату.","criteria":["Я пишу промпт с ролью, задачей, контекстом и форматом.","Я оцениваю ответ ИИ по критериям и улучшаю промпт не менее двух раз.","Я объясняю, какие изменения запроса улучшили результат."],"result":"Карточка промпта проекта: версия 1, 2 и 3 запроса, ответы ИИ, оценка по критериям и итоговый «эталонный» промпт команды.","stages":[{"stage":"Разминка «Найди пару»","min":4},{"stage":"Постановка задачи","min":4},{"stage":"Работа в командах","min":20},{"stage":"Промежуточный показ","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Искусственный интеллект (artificial intelligence)","real":"Программы, решающие задачи, требующие мышления","shown":"Программы, решающие задачи, требующие мышления","truth":true,"first":"И"},{"term":"Проект (project)","real":"Работа с конкретным результатом и сроком","shown":"Сведения о ситуации, аудитории и ограничениях","truth":false,"first":"П"},{"term":"Практика (practice)","real":"Применение знаний на реальной задаче","shown":"Применение знаний на реальной задаче","truth":true,"first":"П"},{"term":"Промпт","real":"Текст запроса к ИИ","shown":"Работа с конкретным результатом и сроком","truth":false,"first":"П"},{"term":"Роль","real":"Кем ИИ должен «быть» в ответе (маркетолог, редактор, аналитик)","shown":"Кем ИИ должен «быть» в ответе (маркетолог, редактор, аналитик)","truth":true,"first":"Р"},{"term":"Контекст","real":"Сведения о ситуации, аудитории и ограничениях","shown":"Текст запроса к ИИ","truth":false,"first":"К"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Искусственный интеллект (artificial intelligence)","def":"Программы, решающие задачи, требующие мышления"},{"term":"Проект (project)","def":"Работа с конкретным результатом и сроком"},{"term":"Практика (practice)","def":"Применение знаний на реальной задаче"},{"term":"Промпт","def":"Текст запроса к ИИ"},{"term":"Роль","def":"Кем ИИ должен «быть» в ответе (маркетолог, редактор, аналитик)"},{"term":"Контекст","def":"Сведения о ситуации, аудитории и ограничениях"},{"term":"Формат","def":"Вид ответа: таблица, список, объём, стиль"},{"term":"Итерация","def":"Повтор цикла «запрос — ответ — улучшение»"}],"english":"project — проект; artificial intelligence — искусственный интеллект; practice — практика","concepts":{"head":"Определения","items":["Промпт — инструкция для искусственного интеллекта (artificial intelligence).","Чем точнее промпт, тем меньше правок.","Практика (practice) урока — промпт для реальной задачи проекта (project)."]},"steps":{"head":"Как это работает, по шагам","items":["Схема РЗКФ: Роль — «Ты маркетолог школьного эко-проекта». Задача — «Напиши 3 варианта поста о запуске». Контекст — «Аудитория 16–20 лет, Павлодар, продаём сумки из переработанной ткани, бюджет маленький, тон дружелюбный, без преувеличений». Формат — «Таблица: заголовок до 7 слов, текст до 60 слов, призыв к действию». Цикл:","Написать версию 1","Оценить ответ по критериям (точность, соответствие аудитории, формат, оригинальность)","Найти, чего не хватило, и добавить в промпт (пример, ограничение, запрет)","Повторить","Проверить факты и не передавать ИИ персональные данные"]},"scheme":"Четыре блока Р — З — К — Ф и круговая стрелка «запрос → ответ → оценка → улучшение».","examples":[{"lab":"Казахстанский","text":"Команда из Павлодара написала «Придумай пост про сумки» — ответ вышел общим и слишком «рекламным». Версия 3 по РЗКФ с примером удачного поста дала тексты, которые почти не пришлось править."},{"lab":"Второй пример","text":"Запрос «Сделай анализ конкурентов» без контекста дал выдуманные компании; после добавления «используй только список из 3 конкурентов ниже» ответ стал проверяемым."}],"mistake":{"myth":"Менять сразу всё и не понимать, что помогло","fix":"В каждой итерации меняем 1–2 элемента и записываем."},"check":[{"q":"Зачем ИИ роль?","a":"Задаёт стиль и уровень экспертизы"},{"q":"Что улучшает ответ сильнее всего?","a":"Контекст и пример"},{"q":"Почему нельзя вставлять в промпт телефоны клиентов?","a":"Персональные данные"}],"kz":{"text":"Технопарк Astana Hub в Астане поддерживает IT-стартапы Казахстана, в том числе команды, создающие продукты на основе ИИ, и проводит для них образовательные программы.","link":"работа с ИИ-инструментами — практический навык для стартапа."},"world":{"text":"Многие компании мира уже публикуют вакансии и внутренние курсы по работе с ИИ-инструментами, а умение ставить задачи ИИ становится частью цифровой грамотности (ЦУР ООН 4.4 — навыки для достойной работы).","link":""},"fact":"Компания Anthropic, создатель ассистента Claude, и OpenAI публикуют официальные руководства по составлению промптов, где советуют давать модели роль, контекст, примеры и желаемый формат ответа.","cards":[{"n":"1","title":"Карточка промпта","lines":["Задача проекта: ___.","Версия 1 (как написали бы обычно): ___. Оценка ответа (1–5): точность, аудитория, формат, оригинальность.","Версия 2 (добавили роль и контекст): ___. Оценка.","Версия 3 (добавили формат и пример): ___. Оценка.","Эталонный промпт: ___. Что помогло больше всего: ___."],"hand":"Сдать: заполненную карточку.","answers":[]},{"n":"2","title":"Слабые промпты для тренировки","lines":["1) «Напиши слоган».","2) «Сделай анализ рынка».","3) «Придумай пост для Instagram».","Задание: перепишите один по схеме РЗКФ для своего проекта.","Правило безопасности: не вставлять имена, телефоны и данные клиентов."],"hand":"Сдать: исправленный промпт.","answers":[]}],"practice":[{"type":"case","title":"Плохой и хороший промпт","minutes":9,"source":"Условная ситуация","hook":"«Напиши пост про наш проект» — и ИИ выдаёт скучный текст. Что не так?","story":["Команда просит ИИ: «Напиши пост про наш проект».","Получается общий текст: «Наш проект — это инновационное решение…».","Капитан говорит: «ИИ плохо пишет»."],"question":"Чего не хватает в промпте?","options":["Слова «пожалуйста»","Восклицательных знаков","Ничего, ИИ просто плохой","Роли, задачи, аудитории, формата и примеров"],"answerIndex":3,"reveal":"Хороший промпт: роль («ты SMM-специалист»), задача, контекст (что за проект, для кого), формат (до 60 слов, 1 эмодзи, призыв), ограничения (без «инновационный»), пример стиля. Чем точнее запрос, тем лучше результат.","teams":"Команды: напишите промпт для задачи своего проекта по схеме «роль — задача — контекст — формат — ограничения». Сравните ответы на плохой и хороший промпт.","takeaway":"Качество ответа зависит от качества промпта."},{"type":"case","title":"Итерация промпта","minutes":8,"source":"Условная ситуация","hook":"Первый ответ ИИ — черновик. Как довести его до результата?","story":["Команда получила от ИИ 5 слоганов для ярмарки, но они длинные и банальные.","Одни хотят взять лучший из пяти, другие — написать всё заново самим.","Третий вариант — продолжить диалог с ИИ."],"question":"Что лучше всего сделать?","options":["Взять первый попавшийся","Дать обратную связь: «короче, до 4 слов, с игрой слов, без клише» и попросить новые варианты","Отказаться от ИИ","Попросить «сделай лучше» без деталей"],"answerIndex":1,"reveal":"Работа с ИИ — это диалог: конкретная обратная связь улучшает результат. А финальный выбор и проверка всегда за человеком.","teams":"Команды: проведите 3 итерации промпта и запишите, что меняли каждый раз.","takeaway":"Промпт улучшают итерациями с конкретной обратной связью."}],"homework":"Примени эталонный промпт команды к новой задаче проекта, проведи 2 итерации и запиши, что изменил и почему.","support":"Шаблон РЗКФ с примерами в каждом блоке; список «что можно добавить в промпт»: пример, ограничение объёма, запрет, аудитория.","advanced":"Написать промпт, который заставляет ИИ задать уточняющие вопросы перед ответом, и сравнить результат.","photo":{"src":"lessons/img/11_24.jpg","author":"Glenn Carstens-Peters","q":["Что вы видите на фото? Как это связано с нашей темой?","Чем умение написать хороший промпт похоже на умение поставить задачу человеку?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g11-l24.pptx","name":"24. Промпт для ИИ — практикум на задаче своего проекта (11 кл).pptx","mb":1.5}},{"id":"11_25","g":11,"l":25,"topic":"Сравнение ИИ-ассистентов: Claude, ChatGPT и другие","module":"Искусственный интеллект","format":"Комбинированный","skills":["Критическое мышление","Принятие решений"],"goal":"К концу урока ученик сможет дать одну и ту же бизнес-задачу двум ИИ-ассистентам и сравнить ответы по точности, полноте и источникам с итоговым выбором и обоснованием.","criteria":["Я формулирую одинаковый запрос и честно сравниваю ответы двух ассистентов.","Я оцениваю точность, полноту и источники и проверяю минимум 2 факта.","Я делаю вывод, основанный на доказательствах, а не на впечатлении."],"result":"Сравнительная таблица двух ИИ-ассистентов по одной задаче проекта: оценки по 3 критериям с доказательствами, найденные ошибки и вывод «для какой задачи какой ассистент».","stages":[{"stage":"Разминка «Правда или ловушка?»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Искусственный интеллект (artificial intelligence)","real":"Программы, решающие задачи, требующие мышления","shown":"Программы, решающие задачи, требующие мышления","truth":true,"first":"И"},{"term":"Бизнес (business)","real":"Деятельность ради прибыли через решение проблем клиентов","shown":"Документ или сайт, на котором основан факт и который можно проверить","truth":false,"first":"Б"},{"term":"ИИ-ассистент","real":"Сервис на основе языковой модели для диалога и выполнения задач (например, Claude компании Anthropic, ChatGPT компании OpenAI, Gemini компании Google)","shown":"Сервис на основе языковой модели для диалога и выполнения задач (например, Claude компании Anthropic, ChatGPT компании OpenAI, Gemini компании Google)","truth":true,"first":"И"},{"term":"Точность","real":"Насколько факты и расчёты в ответе верны","shown":"Деятельность ради прибыли через решение проблем клиентов","truth":false,"first":"Т"},{"term":"Полнота","real":"Насколько ответ покрывает все части задачи","shown":"Насколько ответ покрывает все части задачи","truth":true,"first":"П"},{"term":"Источник","real":"Документ или сайт, на котором основан факт и который можно проверить","shown":"Насколько факты и расчёты в ответе верны","truth":false,"first":"И"}],"perm":[1,0,5,4,3,2]},"glossary":[{"term":"Искусственный интеллект (artificial intelligence)","def":"Программы, решающие задачи, требующие мышления"},{"term":"Бизнес (business)","def":"Деятельность ради прибыли через решение проблем клиентов"},{"term":"ИИ-ассистент","def":"Сервис на основе языковой модели для диалога и выполнения задач (например, Claude компании Anthropic, ChatGPT компании OpenAI, Gemini компании Google)"},{"term":"Точность","def":"Насколько факты и расчёты в ответе верны"},{"term":"Полнота","def":"Насколько ответ покрывает все части задачи"},{"term":"Источник","def":"Документ или сайт, на котором основан факт и который можно проверить"},{"term":"Слепое сравнение","def":"Оценка ответов без знания, какой ассистент их дал"}],"english":"artificial intelligence — искусственный интеллект; business — бизнес","concepts":{"head":"Определения","items":["ИИ-ассистенты — продукты разных компаний: Claude (Anthropic), ChatGPT (OpenAI), Gemini (Google) и другие.","Они построены на разных моделях, обучены на разных данных и обновляются в разное время, поэтому на одну задачу дают разные ответы.","Для бизнеса (business) важно выбирать инструмент искусственного интеллекта (artificial intelligence) по результатам, а не по рекламе."]},"steps":{"head":"Как сравнивать, по шагам","items":["Выбрать задачу проекта (например, «составь план продвижения на месяц и посчитай бюджет»)","Один и тот же промпт по схеме «роль, задача, контекст, формат» отправить двум ассистентам","Перемешать ответы и оценивать вслепую: А и Б","Точность — проверить минимум 2 факта и все расчёты","Полнота — отмечаем, выполнены ли все части задачи","Источники — есть ли ссылки и существуют ли они","Вывод с примерами"]},"scheme":"Таблица 3 × 2: критерии «точность — полнота — источники» × «ассистент А — ассистент Б», в каждой ячейке балл 1–5 и доказательство.","examples":[{"lab":"Казахстанский","text":"Команда из Алматы спросила двух ассистентов о ставке НДС в Казахстане в 2026 году: один назвал 16%, второй — устаревшее значение; проверка на kgd.gov.kz показала, кто прав."},{"lab":"Второй пример","text":"Один ассистент дал подробный план без расчёта бюджета (неполно), второй посчитал бюджет, но ошибся в сложении (неточно)."}],"mistake":{"myth":"Выбирать ассистента по «уверенному стилю»","fix":"Уверенный текст с неверной цифрой хуже скромного, но точного."},"check":[{"q":"Зачем оценивать вслепую?","a":"Чтобы не влияли симпатии к бренду"},{"q":"Что важнее для бизнес-расчёта — точность или красота текста?","a":"Точность"},{"q":"Достаточно ли того, что ассистент дал ссылку?","a":"Нет, ссылку нужно открыть и проверить"}],"kz":{"text":"В Казахстане развивают собственные ИИ-решения: институт ISSAI Назарбаев Университета создал языковую модель KazLLM с поддержкой казахского языка.","link":"при сравнении ассистентов важно проверять и качество ответов на казахском."},"world":{"text":"Независимые исследователи и университеты публикуют рейтинги и тесты языковых моделей, а результаты быстро меняются с новыми версиями; в ЕС принят Закон об ИИ (AI Act, 2024), требующий прозрачности от поставщиков.","link":""},"fact":"Компания Anthropic, создавшая ассистента Claude, была основана в 2021 году бывшими сотрудниками OpenAI; ChatGPT от OpenAI вышел в ноябре 2022 года, а первая версия Claude стала публично доступна в марте 2023 года.","cards":[{"n":"1","title":"Задача для сравнения","lines":["Промпт: «Ты маркетолог школьного проекта в Казахстане. Задача: предложи план продвижения кофе-точки у колледжа на месяц с бюджетом 100 000 условных тенге. Контекст: аудитория 16–22 лет, город Караганда. Формат: таблица из 4 недель (канал, действие, бюджет), итог бюджета и 2 факта о рынке с источниками».","Отправьте одинаково двум ассистентам. Тренер или другой участник перемешивает"],"hand":"Сдать: оба ответа с пометками.","answers":[["","«А» и «Б»."]]},{"n":"2","title":"Лист оценки","lines":["Критерий | А (1–5) | доказательство | Б (1–5) | доказательство","Точность (проверены 2 факта и сумма бюджета = 100 000?)","Полнота (все 4 недели, итог, 2 факта?)","Источники (ссылки открываются и подтверждают факт?)","Вывод: для каких задач лучше А, для каких — Б."],"hand":"Сдать: заполненный лист.","answers":[]}],"practice":[{"type":"case","title":"Один вопрос — три ассистента","minutes":9,"source":"Условная ситуация (сравнение ИИ-ассистентов: Claude, ChatGPT и другие)","hook":"Команда задала один вопрос трём ассистентам. Ответы разные. Кому верить?","story":["Вопрос: «Составь план продвижения школьной ярмарки на 2 недели с бюджетом 10 000 тенге».","Ассистент 1 дал подробный план, но превысил бюджет.","Ассистент 2 дал короткий план в бюджете. Ассистент 3 задал уточняющие вопросы."],"question":"Как правильно сравнивать ИИ-ассистентов?","options":["По известности бренда","По длине ответа","По скорости ответа","По одинаковому заданию и заранее выбранным критериям: точность, соблюдение условий, полезность"],"answerIndex":3,"reveal":"Ассистенты различаются: в стиле, точности, работе с длинными текстами, проверке фактов. Честное сравнение: одно задание, одинаковые критерии, проверка человеком. Ни одному ответу не стоит верить без проверки.","teams":"Команды: составьте таблицу сравнения: задание, критерии (1–5 баллов), итог. Проверьте на задаче своего проекта.","takeaway":"Ассистентов сравнивают на одной задаче по одним критериям."},{"type":"case","title":"Какой ассистент для какой задачи","minutes":8,"source":"Условная ситуация","hook":"Задачи разные: перевод, код для сайта, анализ таблицы продаж. Нужен ли один ассистент на всё?","story":["Команде нужно: перевести описание товара на казахский и английский, сделать простую страницу сайта и проанализировать таблицу продаж.","Один участник предлагает пользоваться только одним ассистентом.","Другой — проверить несколько и выбрать лучший для каждой задачи."],"question":"Какой подход разумнее?","options":["Выбрать самый популярный","Проверить ассистентов на каждой задаче и выбрать лучший результат","Пользоваться одним, не проверяя","Не пользоваться ИИ"],"answerIndex":1,"reveal":"Разные модели сильны в разных задачах, и это быстро меняется. Полезная привычка — быстро протестировать на своей задаче и проверить результат.","teams":"Команды: протестируйте 2 ассистента на одной задаче проекта и обоснуйте выбор.","takeaway":"Выбирают ассистента под задачу, а не по моде."}],"homework":"Повтори сравнение двух ассистентов на другой задаче проекта (например, текст для покупателей) и напиши вывод на 80–100 слов с 2 доказательствами.","support":"Готовый промпт для отправки; таблица с подсказками «что проверить».","advanced":"Добавить третьего ассистента и критерий «стоимость и доступность» и оценить, какой выгоднее для малого бизнеса.","photo":{"src":"lessons/img/11_25.jpg","author":"Growtika","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему вчерашний «лучший» ассистент может завтра проиграть?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g11-l25.pptx","name":"25. Сравнение ИИ-ассистентов — Claude, ChatGPT и другие (11 кл).pptx","mb":1.5}},{"id":"11_26","g":11,"l":26,"topic":"ИИ-контент для бренда: тексты и визуалы: практикум","module":"Искусственный интеллект","format":"Проектная мастерская","skills":["Командная работа","Креативность","Работа с клиентом"],"goal":"К концу урока ученик сможет создать с помощью ИИ пост для бренда проекта (текст и визуал) и отредактировать его под фирменный стиль и тон бренда.","criteria":["Я пишу промпт с учётом аудитории и тона бренда.","Я редактирую текст и визуал ИИ под фирменный стиль и проверяю факты.","Я объясняю, что изменил и почему, и соблюдаю правила авторства."],"result":"Готовый пост бренда: исходный ИИ-вариант, отредактированный текст и визуал по брендбуку, чек-лист соответствия стилю и пометка «создано с помощью ИИ».","stages":[{"stage":"Разминка «Угадай слово»","min":4},{"stage":"Постановка задачи","min":4},{"stage":"Работа в командах","min":20},{"stage":"Промежуточный показ","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Бренд (brand)","real":"Образ продукта или компании в сознании людей","shown":"Образ продукта или компании в сознании людей","truth":true,"first":"Б"},{"term":"Искусственный интеллект (artificial intelligence)","real":"Программы, решающие задачи, требующие мышления","shown":"Правила фирменного стиля: логотип, цвета, шрифты, тон","truth":false,"first":"И"},{"term":"Практика (practice)","real":"Применение знаний на реальной задаче","shown":"Применение знаний на реальной задаче","truth":true,"first":"П"},{"term":"Тон бренда (tone of voice)","real":"Характер общения бренда: дружелюбный, экспертный, дерзкий","shown":"Программы, решающие задачи, требующие мышления","truth":false,"first":"Т"},{"term":"Визуал","real":"Изображение или графика к посту","shown":"Изображение или графика к посту","truth":true,"first":"В"},{"term":"Брендбук","real":"Правила фирменного стиля: логотип, цвета, шрифты, тон","shown":"Характер общения бренда: дружелюбный, экспертный, дерзкий","truth":false,"first":"Б"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Бренд (brand)","def":"Образ продукта или компании в сознании людей"},{"term":"Искусственный интеллект (artificial intelligence)","def":"Программы, решающие задачи, требующие мышления"},{"term":"Практика (practice)","def":"Применение знаний на реальной задаче"},{"term":"Тон бренда (tone of voice)","def":"Характер общения бренда: дружелюбный, экспертный, дерзкий"},{"term":"Визуал","def":"Изображение или графика к посту"},{"term":"Брендбук","def":"Правила фирменного стиля: логотип, цвета, шрифты, тон"},{"term":"Контент-план","def":"Расписание публикаций с темами"}],"english":"brand — бренд; artificial intelligence — искусственный интеллект; practice — практика","concepts":{"head":"Определения","items":["Контент бренда (brand) — посты, тексты, изображения.","Искусственный интеллект (artificial intelligence) быстро даёт черновик, но «голос» бренда задаёт человек.","Практика (practice) урока — пост для своего проекта."]},"steps":{"head":"Как это работает, по шагам","items":["Открыть брендбук: цвета, шрифт, тон, запретные слова","Промпт для текста по схеме РЗКФ с описанием тона и примером удачного поста","Промпт для визуала: объект, стиль, цвета бренда, без текста на картинке (текст добавим сами)","Редактура текста: убрать штампы («уникальный», «лучший»), проверить факты, сократить, добавить призыв к действию","Редактура визуала в редакторе: логотип, фирменные цвета и шрифт","Чек-лист соответствия","Пометка о помощи ИИ и проверка, что изображение не копирует чужой бренд или человека"]},"scheme":"«конвейер контента»: брендбук → промпт → ИИ-черновик → редактура человеком → чек-лист → публикация.","examples":[{"lab":"Казахстанский","text":"Команда эко-сумок из Костаная получила от ИИ текст «Уникальные сумки премиум-класса для лучших людей!». После редактуры под дружелюбный тон: «Сумка из старых джинсов, которая выдержит и учебники, и рынок. 4 500 ₸, заказы — в директ»."},{"lab":"Второй пример","text":"ИИ нарисовал сумку в розовых тонах, хотя цвета бренда — зелёный и бежевый; команда перекрасила фон и добавила логотип."}],"mistake":{"myth":"«Красиво — значит готово»","fix":"Пост должен соответствовать бренду и быть правдивым."},"check":[{"q":"Почему нельзя публиковать ИИ-текст без правок?","a":"Штампы, ошибки, чужой тон"},{"q":"Зачем писать текст поверх картинки самим?","a":"ИИ часто искажает надписи"},{"q":"Что проверить в визуале?","a":"Цвета, логотип, нет копирования чужого"}],"kz":{"text":"Казахстанские бренды активно ведут соцсети на казахском и русском языках, и сохранение единого тона на двух языках — важная задача. Пример — авиакомпания Air Astana, чей стиль коммуникации связан с гостеприимством и узнаваемой айдентикой.","link":""},"world":{"text":"Крупные платформы и бренды в мире вводят маркировку контента, созданного ИИ, а в ЕС Закон об ИИ (AI Act) требует обозначать некоторые виды синтетического контента. Это связано с ЦУР ООН 16.10 — доступ к достоверной информации.","link":""},"fact":"Кампания Coca-Cola «Share a Coke», где на бутылках печатали популярные имена, стартовала в Австралии в 2011 году и затем прошла более чем в 70 странах; она показала силу персонализированного контента.","cards":[{"n":"1","title":"Промпты","lines":["Текст: «Ты SMM-специалист бренда ___. Тон: ___. Аудитория: ___. Задача: пост о ___ до 60 слов с призывом к действию. Не используй слова: уникальный, лучший, премиум. Пример нашего удачного поста: ___».","Визуал: «Фото-стиль, объект ___, фон в цветах ___, без текста и людей, без чужих логотипов»."],"hand":"Сдать: промпты и черновики.","answers":[]},{"n":"2","title":"Чек-лист соответствия бренду","lines":["Цвета и шрифт по брендбуку.","Логотип на месте.","Тон соответствует.","Нет штампов.","Факты и цена проверены.","Есть призыв к действию.","Нет чужих лиц и брендов.","Пометка «создано с помощью ИИ».","Есть версия на казахском."],"hand":"Сдать: отмеченный чек-лист.","answers":[]}],"practice":[{"type":"case","title":"Рождественская реклама от ИИ","minutes":9,"source":"Рождественская реклама Coca-Cola, созданная с помощью генеративного ИИ, ноябрь 2024","hook":"Знаменитую рождественскую рекламу переделали с помощью ИИ. Зрители отреагировали неожиданно.","story":["Coca-Cola много лет показывает рождественский ролик с красными грузовиками «Holidays Are Coming».","В 2024 году компания выпустила новую версию, созданную с помощью генеративного ИИ.","Многие зрители и дизайнеры раскритиковали её: «бездушно», «странные лица и колёса»."],"question":"Какой урок для брендов, которые делают ИИ-контент?","options":["ИИ-контент всегда нравится","Зрители не замечают разницы","ИИ ускоряет работу, но качество, эмоции и проверка остаются за людьми","Нельзя использовать ИИ вообще"],"answerIndex":2,"reveal":"Ролик обсуждали больше из-за критики, чем из-за праздника. Аудитория замечает «искусственность» и ценит душу бренда. ИИ — помощник, но финальное качество и честность — ответственность команды.","teams":"Команды: создайте с ИИ 3 варианта поста для бренда и выберите лучший по критериям: голос бренда, точность, эмоция.","takeaway":"ИИ-контент проверяют на голос бренда и качество."},{"type":"case","title":"Голос бренда для нейросети","minutes":8,"source":"Условная ситуация","hook":"ИИ пишет посты то официально, то с мемами. Бренд «расползается».","story":["Команда ведёт аккаунт ярмарочного бренда «Чай с бабушкой».","Каждый участник просит ИИ писать посты по-своему.","В ленте: один пост — как отчёт министерства, другой — с мемами и сленгом."],"question":"Как сделать посты одинаковыми по стилю?","options":["Запретить ИИ","Написать «гайд голоса бренда» и добавлять его в каждый промпт","Пусть пишет один человек без правил","Публиковать всё подряд"],"answerIndex":1,"reveal":"Гайд голоса бренда: 3 слова о характере («тёплый, честный, домашний»), что можно и что нельзя, примеры. Его вставляют в промпт — и ИИ пишет в одном стиле.","teams":"Команды: напишите гайд голоса бренда своего проекта (5 строк) и проверьте его на ИИ.","takeaway":"Единый голос бренда задают правилами в промпте."}],"homework":"Составь контент-план бренда на неделю (3 поста) и подготовь один пост полностью: промпт, черновик ИИ, отредактированная версия, пометка о помощи ИИ.","support":"Шаблон промпта для текста и визуала; список штампов, которые нужно убрать.","advanced":"Сделать два варианта поста для разных сегментов аудитории и объяснить различия в тоне.","photo":{"src":"lessons/img/11_26.jpg","author":"Glenn Carstens-Peters","q":["Что вы видите на фото? Как это связано с нашей темой?","Должен ли бренд сообщать аудитории, что пост сделан с помощью ИИ?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g11-l26.pptx","name":"26. ИИ-контент для бренда — тексты и визуалы — практикум (11 кл).pptx","mb":1.4}},{"id":"11_27","g":11,"l":27,"topic":"После ярмарки: оценка бренда покупателями","module":"Стратегический маркетинг","format":"Симуляция, ярмарка","skills":["Работа с клиентом","Критическое мышление","Принятие решений"],"goal":"К концу урока ученик сможет проанализировать оценку бренда покупателями по итогам ярмарки (опрос, NPS, наблюдения, продажи) и сформулировать 3 решения по улучшению бренда.","criteria":["Я собираю и правильно обрабатываю оценки покупателей, считаю NPS.","Я связываю оценки с цифрами продаж и наблюдениями.","Я формулирую 3 решения по улучшению бренда с обоснованием."],"result":"Отчёт «Бренд глазами покупателей»: результаты опроса, расчёт NPS, связь с продажами и 3 конкретных решения по упаковке, стилю или сервису.","stages":[{"stage":"Разминка «Найди пару»","min":4},{"stage":"Подготовка","min":6},{"stage":"Ярмарка","min":18},{"stage":"Подсчёт","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Ярмарка (fair)","real":"Учебная торговая площадка с условными тенге","shown":"Учебная торговая площадка с условными тенге","truth":true,"first":"Я"},{"term":"Покупатель (customer)","real":"Человек, который приобретает продукт","shown":"Покупатель, поставивший 9–10; критик — 0–6; нейтральный — 7–8","truth":false,"first":"П"},{"term":"Бренд (brand)","real":"Образ продукта в сознании покупателей","shown":"Образ продукта в сознании покупателей","truth":true,"first":"Б"},{"term":"Маркетинг (marketing)","real":"Изучение клиентов и продвижение продукта","shown":"Человек, который приобретает продукт","truth":false,"first":"М"},{"term":"NPS (индекс потребительской лояльности)","real":"Доля «промоутеров» минус доля «критиков» по вопросу «порекомендуете ли вы нас другу?» по шкале 0–10","shown":"Доля «промоутеров» минус доля «критиков» по вопросу «порекомендуете ли вы нас другу?» по шкале 0–10","truth":true,"first":"N"},{"term":"Промоутер","real":"Покупатель, поставивший 9–10; критик — 0–6; нейтральный — 7–8","shown":"Изучение клиентов и продвижение продукта","truth":false,"first":"П"}],"perm":[3,2,1,0,5,4]},"glossary":[{"term":"Ярмарка (fair)","def":"Учебная торговая площадка с условными тенге"},{"term":"Покупатель (customer)","def":"Человек, который приобретает продукт"},{"term":"Бренд (brand)","def":"Образ продукта в сознании покупателей"},{"term":"Маркетинг (marketing)","def":"Изучение клиентов и продвижение продукта"},{"term":"NPS (индекс потребительской лояльности)","def":"Доля «промоутеров» минус доля «критиков» по вопросу «порекомендуете ли вы нас другу?» по шкале 0–10"},{"term":"Промоутер","def":"Покупатель, поставивший 9–10; критик — 0–6; нейтральный — 7–8"},{"term":"Обратная связь покупателя","def":"Мнения, отзывы и оценки клиентов"}],"english":"fair — ярмарка; customer — покупатель; brand — бренд; marketing — маркетинг","concepts":{"head":"Определения","items":["Бренд (brand) — это то, что о нас думает покупатель (customer), а не то, что думаем мы.","Маркетинг (marketing) измеряет это опросами и поведением.","NPS — простой показатель лояльности."]},"steps":{"head":"Как это работает, по шагам","items":["Собрать оценки, полученные на ярмарке (fair): вопрос «От 0 до 10 — порекомендуете ли наш продукт другу?» и вопрос «Почему?»","Разделить ответы: 9–10 промоутеры, 7–8 нейтральные, 0–6 критики","NPS = % промоутеров − % критиков (от −100 до +100)","Сгруппировать причины: упаковка, вкус/качество, цена, продавец","Сопоставить с продажами и конверсией из журнала","Сформулировать 3 решения"]},"scheme":"Шкала 0–10, раскрашенная: красная 0–6, жёлтая 7–8, зелёная 9–10; формула NPS; справа «облако причин».","examples":[{"lab":"Казахстанский","text":"Команда из Шымкента собрала 20 оценок: 9 промоутеров, 7 нейтральных, 4 критика. NPS = 45% − 20% = 25. Критики писали «дорого» и «непонятно, что внутри». Решение: добавить на упаковку состав и размер, ввести мини-версию за меньшую цену."},{"lab":"Второй пример","text":"У команды с NPS 60 продажи были низкими — оценки ставили только те, кто купил, а подходившие уходили: значит, нужно улучшать видимость стенда, а не продукт."}],"mistake":{"myth":"Опросить только друзей","fix":"Выборка искажена, вывод будет слишком оптимистичным."},"check":[{"q":"Почему нейтральные не входят в формулу?","a":"Они не рекомендуют и не ругают"},{"q":"Может ли NPS быть отрицательным?","a":"Да, если критиков больше"}],"kz":{"text":"Многие казахстанские сервисы, например банки и сервисы доставки, просят клиентов оценить обслуживание после операции в приложении.","link":"так компании постоянно измеряют отношение покупателей к бренду."},"world":{"text":"Индекс NPS предложил Фред Райхельд в статье в Harvard Business Review в 2003 году, и сегодня им пользуются компании по всему миру. Уважение к мнению потребителя связано с ЦУР ООН 12.","link":""},"fact":"Статья Фреда Райхельда «The One Number You Need to Grow» вышла в Harvard Business Review в декабре 2003 года и дала начало методике NPS.","cards":[{"n":"1","title":"Обработка оценок","lines":["Таблица: № | Оценка 0–10 | Группа (П/Н/К) | Почему? | Купил?","Итоги: всего ___; промоутеров ___ (___%); нейтральных ___; критиков ___ (___%); NPS = ___.","Причины (сгруппируйте): упаковка, качество, цена, продавец, другое."],"hand":"Сдать: таблицу.","answers":[["","Да/нет"]]},{"n":"2","title":"Экспресс-опрос и наблюдения","lines":["Вопросы покупателю: 1) «От 0 до 10: порекомендуете ли наш продукт другу?» 2) «Почему?» 3) «Что изменить в упаковке?»","Наблюдения галереи: у какой команды самый высокий NPS и что у неё особенного?","Пример для проверки: 25 оценок — 12 по 9–10, 8 по 7–8, 5 по 0–6. NPS?"],"hand":"Сдать: ответы и наблюдения.","answers":[["","48% − 20% = 28."]]}],"practice":[{"type":"case","title":"Один главный вопрос","minutes":9,"source":"Индекс NPS, Фред Райхельд, статья в Harvard Business Review, 2003","hook":"Какой один вопрос лучше всего показывает, любят ли клиенты бренд?","story":["Консультант Фред Райхельд искал простой способ измерить отношение клиентов к компании.","Он предложил один вопрос: «Насколько вероятно, что вы порекомендуете нас другу?» — от 0 до 10.","Тех, кто ставит 9–10, называют сторонниками, 0–6 — критиками."],"question":"Как считается NPS?","options":["Средняя оценка","Процент сторонников минус процент критиков","Число отзывов","Процент тех, кто поставил 10"],"answerIndex":1,"reveal":"NPS = % сторонников (9–10) − % критиков (0–6). Оценки 7–8 — нейтральные. Метод стал одним из самых распространённых способов измерять лояльность клиентов.","teams":"Команды: посчитайте NPS по ответам покупателей ярмарки (или условным: 12 сторонников, 5 нейтральных, 3 критика из 20).","takeaway":"NPS: порекомендуют ли вас друзьям."},{"type":"case","title":"Что запомнили покупатели","minutes":8,"source":"Условная ситуация","hook":"Бренд старался 2 недели. Что из этого запомнилось людям?","story":["Команда спросила 20 покупателей после ярмарки.","Название бренда вспомнили 14, слоган — 4, фирменный цвет — 16.","Логотип не смог описать никто."],"question":"Что команде стоит улучшить в первую очередь?","options":["Цвет","Слоган и логотип — их почти не запомнили","Название","Ничего"],"answerIndex":1,"reveal":"Цвет запомнили 80%, название — 70%, а слоган — только 20%. Значит, слоган нужно сделать короче или чаще повторять, а логотип — проще. Оценка покупателей показывает, что реально работает.","teams":"Команды: составьте анкету из 4 вопросов для оценки бренда покупателями и предложите 2 улучшения.","takeaway":"Бренд оценивают по памяти покупателей, а не по ощущениям команды."}],"homework":"Оформи отчёт «Бренд глазами покупателей»: NPS, 3 главные причины, связь с продажами, 3 решения. Сделай набросок улучшенной упаковки.","support":"Шаблон таблицы с цветовой разметкой 0–6, 7–8, 9–10; пример расчёта NPS.","advanced":"Сравнить NPS двух групп покупателей (купившие и не купившие) и объяснить разницу.","photo":{"src":"lessons/img/11_27.jpg","author":"Towfiqu barbhuiya","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему один вопрос «порекомендуете ли?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g11-l27.pptx","name":"27. После ярмарки — оценка бренда покупателями (11 кл).pptx","mb":1.3}},{"id":"11_28","g":11,"l":28,"topic":"ИИ-аналитика: сегментация клиентов: практикум","module":"Искусственный интеллект","format":"Проектная мастерская","skills":["Работа с клиентом","Критическое мышление","Командная работа"],"goal":"К концу урока ученик сможет разделить клиентов проекта на сегменты с помощью ИИ и проверить логику сегментации по данным.","criteria":["Я готовлю обезличенные данные и пишу промпт для сегментации.","Я проверяю, что сегменты ИИ подтверждаются данными, и нахожу ошибки.","Я выбираю целевой сегмент и обосновываю выбор."],"result":"Сегментация клиентов проекта: таблица условных данных, 3–4 сегмента от ИИ, проверка по критериям (размер, различимость, доступность, выгодность) и выбор целевого сегмента.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":4},{"stage":"Постановка задачи","min":4},{"stage":"Работа в командах","min":20},{"stage":"Промежуточный показ","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Клиент (client)","real":"Человек или организация, которые покупают продукт","shown":"Человек или организация, которые покупают продукт","truth":true,"first":"К"},{"term":"Искусственный интеллект (artificial intelligence)","real":"Программы, решающие задачи, требующие мышления","shown":"Данные без имён, телефонов и других сведений, по которым можно узнать человека","truth":false,"first":"И"},{"term":"Практика (practice)","real":"Применение знаний на реальной задаче","shown":"Применение знаний на реальной задаче","truth":true,"first":"П"},{"term":"Сегмент","real":"Группа клиентов с похожими потребностями и поведением","shown":"Программы, решающие задачи, требующие мышления","truth":false,"first":"С"},{"term":"Сегментация","real":"Деление клиентов на сегменты","shown":"Деление клиентов на сегменты","truth":true,"first":"С"},{"term":"Обезличенные данные","real":"Данные без имён, телефонов и других сведений, по которым можно узнать человека","shown":"Группа клиентов с похожими потребностями и поведением","truth":false,"first":"О"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Клиент (client)","def":"Человек или организация, которые покупают продукт"},{"term":"Искусственный интеллект (artificial intelligence)","def":"Программы, решающие задачи, требующие мышления"},{"term":"Практика (practice)","def":"Применение знаний на реальной задаче"},{"term":"Сегмент","def":"Группа клиентов с похожими потребностями и поведением"},{"term":"Сегментация","def":"Деление клиентов на сегменты"},{"term":"Обезличенные данные","def":"Данные без имён, телефонов и других сведений, по которым можно узнать человека"},{"term":"Целевой сегмент","def":"Группа, на которую бизнес направляет основные усилия"}],"english":"client — клиент; artificial intelligence — искусственный интеллект; practice — практика","concepts":{"head":"Определения","items":["Клиенты (client) разные: студентам важна цена, офисным работникам — скорость.","Сегментация помогает говорить с каждой группой на её языке.","Искусственный интеллект (artificial intelligence) быстро находит закономерности, но человек проверяет, есть ли они на самом деле.","Практика (practice) — сегментация клиентов проекта."]},"steps":{"head":"Как это работает, по шагам","items":["Собрать обезличенные данные: возраст, частота покупок, средний чек, канал, причина покупки","Промпт: «Ты аналитик. Раздели клиентов на 3–4 сегмента по поведению. Для каждого: название, признаки, доля, средний чек, как с ним общаться. Покажи, какие строки данных относятся к сегменту»","Проверка: пересчитать доли и средние чеки вручную; убедиться, что сегменты различаются; нет ли выдуманных признаков","Оценка по критериям: размер, различимость, доступность, выгодность (размер × средний чек × частота)","Выбрать целевой сегмент"]},"scheme":"Таблица данных → «ИИ: сегменты» → «Проверка: доли, чеки, признаки» → «Критерии» → «Целевой сегмент».","examples":[{"lab":"Казахстанский","text":"Условная кофейня у университета в Астане, 40 записей о клиентах. ИИ выделил «утренние студенты» (45%, чек 900 условных тенге, ежедневно), «офисные выходные» (25%, чек 2 500, раз в неделю), «компании друзей» (30%, чек 4 000, раз в месяц). Проверка показала: в «утренних студентах» на самом деле 40%, а не 45% — ИИ ошибся в подсчёте. Выгодность за месяц: студенты дают больше всего выручки — целевой сегмент."},{"lab":"Второй пример","text":"ИИ придумал сегмент «туристы», хотя в данных не было ни одного туриста — галлюцинация."}],"mistake":{"myth":"Принять сегменты ИИ без пересчёта","fix":"Разбираем ошибку с 45%."},"check":[{"q":"Почему данные должны быть обезличены?","a":"Защита персональных данных"},{"q":"Как поймать выдуманный сегмент?","a":"Попросить показать строки данных"},{"q":"Как оценить выгодность?","a":"Размер × чек × частота"}],"kz":{"text":"В Казахстане действует Закон РК «О персональных данных и их защите», который обязывает компании получать согласие на сбор и обработку персональных данных.","link":"перед сегментацией данные нужно обезличить."},"world":{"text":"Европейский регламент о защите данных GDPR (действует с 2018 года) установил строгие правила работы с персональными данными клиентов, и его требования влияют на компании по всему миру. Это связано с ЦУР ООН 16.","link":""},"fact":"Термин «сегментация рынка» ввёл американский маркетолог Уэнделл Смит в статье 1956 года в Journal of Marketing. С тех пор сегментация — одна из основ маркетинга.","cards":[{"n":"1","title":"Данные кофейни (условные, обезличенные)","lines":["Клиент | Возраст | Покупок в месяц | Средний чек, тенге | Время | Причина","К1 | 19 | 20 | 900 | утро | кофе перед парами","К2 | 34 | 4 | 2 600 | обед | рабочая встреча","К3 | 22 | 2 | 4 200 | вечер | встреча с друзьями","К4 | 18 | 18 | 850 | утро | кофе перед парами","К5 | 41 | 4 | 2 400 | обед | рабочая встреча","К6 | 20 | 1 | 3 800 | вечер | день рождения","К7 | 21 | 22 | 950 | утро | кофе перед парами","К8 | 29 | 5 | 2 500 | обед | работа с ноутбуком","К9 | 23 | 2 | 4 000 | вечер | встреча с друзьями","К10 | 17 | 15 | 800 | утро | кофе перед уроками","К11 | 38 | 3 | 2 700 | обед | рабочая встреча","К12 | 25 | 1 | 4 500 | вечер | встреча с друзьями","Задание: работайте с 12 строками; при желании добавьте строки из опроса своего проекта."],"hand":"Сдать: таблицу с отметкой сегмента для каждой строки.","answers":[]},{"n":"2","title":"Проверка сегментации","lines":["Для каждого сегмента ИИ: доля по данным ___% (пересчитать СЧЁТЕСЛИ); средний чек по данным ___; есть ли в данных признаки, названные ИИ (да/нет); выгодность в месяц = число клиентов × чек × покупок в месяц.","Критерии: размер, различимость, доступность, выгодность (1–5).","Вывод: целевой сегмент ___, потому что ___."],"hand":"Сдать: лист проверки.","answers":[]}],"practice":[{"type":"case","title":"Магазин, который узнал раньше семьи","minutes":9,"source":"Аналитика сети Target, статья Чарльза Дахигга в The New York Times, 2012","hook":"Сеть магазинов по покупкам вычисляла, что покупательница ждёт ребёнка.","story":["Аналитики американской сети Target изучали покупки клиентов.","Они заметили: некоторые покупки — например, лосьон без запаха и определённые витамины — часто покупают женщины в ожидании ребёнка.","Магазин начал отправлять таким клиенткам купоны на детские товары."],"question":"Какой главный вопрос возникает в этой истории?","options":["Этика: где граница между полезной сегментацией и вторжением в личную жизнь","Как печатать купоны","Сколько стоят витамины","Как открыть новый магазин"],"answerIndex":0,"reveal":"Сегментация по данным очень сильна: она находит группы клиентов по поведению. Но история вызвала споры о приватности. В статье описан случай, когда купоны раскрыли тайну семье. Аналитика должна уважать людей.","teams":"Команды: разделите покупателей ярмарки на 3 сегмента по данным (что, когда, сколько купили) и предложите каждому своё предложение.","takeaway":"Сегментация полезна, но должна уважать приватность."},{"type":"case","title":"ИИ делит покупателей","minutes":8,"source":"Условная ситуация","hook":"Таблица 60 покупок ярмарки. ИИ нашёл 3 группы. Можно ли ему верить?","story":["Команда загрузила в ИИ таблицу: время покупки, товар, сумма, класс покупателя.","ИИ выделил 3 сегмента: «утренние сладкоежки», «учителя на перемене», «старшеклассники с большими чеками».","Но в таблице было всего 4 покупки учителей."],"question":"Что нужно сделать перед тем, как использовать эти сегменты?","options":["Сразу запустить рекламу на учителей","Проверить, сколько данных в каждом сегменте и подтверждается ли он таблицей","Удалить таблицу","Попросить ИИ придумать ещё сегменты"],"answerIndex":1,"reveal":"Сегмент из 4 покупок — слишком мало данных для выводов. ИИ ускоряет анализ, но выводы проверяет человек: размер выборки, логика, совпадение с данными.","teams":"Команды: попросите ИИ сегментировать вашу таблицу продаж и проверьте каждый сегмент по 3 вопросам.","takeaway":"Выводы ИИ проверяют по данным и размеру выборки."}],"homework":"Составь обезличенную таблицу из 15–20 потенциальных клиентов своего проекта (по опросу знакомых), сегментируй с ИИ, проверь одну долю и один средний чек вручную.","support":"Готовая таблица кофейни; промпт-шаблон; инструкция по формуле СЧЁТЕСЛИ.","advanced":"Попросить ИИ сегментировать по другому признаку (причина покупки вместо возраста) и сравнить, какая сегментация полезнее для бизнеса.","photo":{"src":"lessons/img/11_28.jpg","author":"Growtika","q":["Что вы видите на фото? Как это связано с нашей темой?","Какие данные клиентов можно использовать для сегментации, а какие — нет?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g11-l28.pptx","name":"28. ИИ-аналитика — сегментация клиентов — практикум (11 кл).pptx","mb":1.5}},{"id":"11_29","g":11,"l":29,"topic":"Ответственная работа с ИИ: проверка фактов, авторство, этика","module":"Искусственный интеллект","format":"Комбинированный","skills":["Критическое мышление","Принятие решений"],"goal":"К концу урока ученик сможет проверить 3 факта из ответа ИИ по надёжным источникам, отметить, где ИИ ошибся, и объяснить правила авторства и этики при работе с ИИ.","criteria":["Я выделяю в ответе ИИ проверяемые утверждения и проверяю 3 из них по надёжным источникам.","Я правильно отмечаю ошибки и объясняю, почему источник надёжен.","Я объясняю правила авторства и этики и честно указываю помощь ИИ."],"result":"Протокол фактчекинга: ответ ИИ, 3 проверенных утверждения с источниками и вердиктом «верно / неверно / не подтверждено», плюс правило честного указания ИИ.","stages":[{"stage":"Разминка «Угадай слово»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Тестирование (testing)","real":"Проверка утверждения или продукта на соответствие правде или требованиям","shown":"Проверка утверждения или продукта на соответствие правде или требованиям","truth":true,"first":"Т"},{"term":"Этика (ethics)","real":"Правила честного и уважительного поведения","shown":"Документ или сайт организации, от которой исходит информация (закон, официальная статистика)","truth":false,"first":"Э"},{"term":"Искусственный интеллект (artificial intelligence)","real":"Программы, решающие задачи, требующие мышления","shown":"Программы, решающие задачи, требующие мышления","truth":true,"first":"И"},{"term":"Ответственность (responsibility)","real":"Готовность отвечать за свои действия и их последствия","shown":"Правила честного и уважительного поведения","truth":false,"first":"О"},{"term":"Фактчекинг","real":"Проверка фактов по независимым источникам","shown":"Проверка фактов по независимым источникам","truth":true,"first":"Ф"},{"term":"Первоисточник","real":"Документ или сайт организации, от которой исходит информация (закон, официальная статистика)","shown":"Готовность отвечать за свои действия и их последствия","truth":false,"first":"П"}],"perm":[1,0,5,4,3,2]},"glossary":[{"term":"Тестирование (testing)","def":"Проверка утверждения или продукта на соответствие правде или требованиям"},{"term":"Этика (ethics)","def":"Правила честного и уважительного поведения"},{"term":"Искусственный интеллект (artificial intelligence)","def":"Программы, решающие задачи, требующие мышления"},{"term":"Ответственность (responsibility)","def":"Готовность отвечать за свои действия и их последствия"},{"term":"Фактчекинг","def":"Проверка фактов по независимым источникам"},{"term":"Первоисточник","def":"Документ или сайт организации, от которой исходит информация (закон, официальная статистика)"},{"term":"Авторство","def":"Право и обязанность указывать, кто создал работу, в том числе с помощью ИИ"}],"english":"testing — тестирование; ethics — этика; artificial intelligence — искусственный интеллект; responsibility — ответственность","concepts":{"head":"Определения","items":["Ответ искусственного интеллекта (artificial intelligence) — черновик, а не истина.","Фактчекинг — это тестирование (testing) утверждений.","Этика (ethics) и ответственность (responsibility): за опубликованный текст отвечает человек, а не ИИ."]},"steps":{"head":"Как проверять, по шагам","items":["Выделить в ответе проверяемые утверждения — числа, даты, имена, законы, цитаты","Выбрать 3 самых важных","Найти первоисточник: закон — adilet.zan.kz; налоги — kgd.gov.kz; статистика — stat.gov.kz; компания — её официальный сайт","Подтвердить вторым независимым источником","Вердикт: «верно», «неверно», «не подтверждено»","Исправить текст. Правила авторства: указывать, где помогал ИИ; не выдавать чужие тексты и изображения за свои; не загружать в ИИ персональные данные; не создавать фейки о реальных людях"]},"scheme":"«фильтр фактов»: ответ ИИ → лупа «проверяемые утверждения» → первоисточник → второй источник → вердикт; сбоку «4 правила авторства».","examples":[{"lab":"Казахстанский","text":"ИИ написал: «В 2026 году ставка НДС в Казахстане не изменилась, а МРП остался прежним». Проверка на kgd.gov.kz показала: в 2026 году НДС 16%, МРП 4 325 тенге — ИИ опирался на устаревшие данные."},{"lab":"Второй пример","text":"В 2023 году в США адвокаты подали в суд документы с выдуманными ChatGPT судебными делами и были оштрафованы — пример ответственности человека за непроверенный ответ ИИ."}],"mistake":{"myth":"Проверять факт, спрашивая тот же ИИ «ты уверен?»","fix":"Модель может повторить ошибку уверенно."},"check":[{"q":"Почему Википедия — не первоисточник?","a":"Это пересказ, нужно смотреть ссылки"},{"q":"Что делать с «не подтверждено»?","a":"Убрать или пометить"},{"q":"Кто отвечает за ошибку в опубликованном тексте?","a":"Автор публикации"}],"kz":{"text":"В Казахстане официальные данные публикуются на государственных ресурсах: законы — на adilet.zan.kz, налоговые ставки — на kgd.gov.kz, статистика — на stat.gov.kz.","link":"именно эти сайты — первоисточники для проверки ответов ИИ о Казахстане."},"world":{"text":"В 2023 году суд в Нью-Йорке оштрафовал адвокатов на 5 000 долларов за ссылки на несуществующие дела, выдуманные ChatGPT (дело Mata против Avianca). ЮНЕСКО в 2021 году приняла Рекомендацию об этике ИИ. Это связано с ЦУР ООН 16.10.","link":""},"fact":"В деле Mata против Avianca (2023) адвокат признал, что использовал ChatGPT для поиска прецедентов и не проверил их; суд назвал шесть дел вымышленными и наложил штраф.","cards":[{"n":"1","title":"Ответ ИИ для проверки","lines":["«Чтобы открыть малый бизнес в Казахстане в 2026 году, достаточно зарегистрировать ИП. На упрощённой декларации налог составляет 4% от дохода. НДС не входит в цену товара, а добавляется на кассе. Базового вычета по ИПН нет. МРП в 2026 году — 4 325 тенге. Пенсионный возраст — 63 года для мужчин и 61 для женщин».","Задание: выделите утверждения, проверьте 3 по первоисточникам, поставьте вердикт."],"hand":"Сдать: протокол.","answers":[["Тренеру","4% — верно; НДС «не входит в цену» — неверно (входит, 16%); «вычета нет» — неверно (30 МРП); МРП 4 325 — верно; 63/61 — верно."]]},{"n":"2","title":"Протокол фактчекинга","lines":["Утверждение | Первоисточник (ссылка) | Второй источник | Вердикт | Исправленный текст.","Правило авторства для проекта: «В этой работе ИИ использовался для ___; факты проверены по ___»."],"hand":"Сдать: протокол и правило.","answers":[]}],"practice":[{"type":"case","title":"Юрист и выдуманные дела","minutes":9,"source":"Дело Mata v. Avianca, суд Нью-Йорка, 2023","hook":"Адвокат подал в суд документ с примерами из прошлых дел. Таких дел не существовало.","story":["Адвокат готовил документ для суда и попросил ChatGPT найти похожие судебные решения.","Ассистент выдал несколько дел с названиями, датами и цитатами.","Адвокат не проверил их и отправил в суд. Оказалось, что дела выдуманы."],"question":"Что пошло не так?","options":["ИИ специально обманул","Суд ошибся","Человек не проверил факты, а ответственность за документ — на нём","Ничего страшного"],"answerIndex":2,"reveal":"Суд оштрафовал адвокатов. ИИ может «галлюцинировать» правдоподобные источники. Правило ответственной работы: всё важное проверять по первоисточникам, а отвечает всегда человек.","teams":"Команды: проверьте 3 факта из ответа ИИ по теме вашего проекта и запишите, где нашли подтверждение.","takeaway":"За текст, сделанный с ИИ, отвечает человек."},{"type":"case","title":"Чат-бот авиакомпании пообещал скидку","minutes":8,"source":"Решение трибунала Британской Колумбии по делу против Air Canada, февраль 2024","hook":"Чат-бот на сайте пообещал клиенту возврат денег по правилам, которых не было.","story":["Пассажир спросил у чат-бота Air Canada о скидке на билет в связи со смертью родственника.","Бот ответил, что можно купить билет и потом подать на частичный возврат денег. По настоящим правилам компании так было нельзя.","Авиакомпания отказала в возврате и заявила, что бот «сам отвечает за свои слова»."],"question":"Что решил трибунал?","options":["Пассажир сам виноват","Дело не рассматривали","Бот отвечает сам за себя","Компания отвечает за слова своего чат-бота и должна выплатить компенсацию"],"answerIndex":3,"reveal":"Трибунал решил, что компания отвечает за всю информацию на своём сайте, включая ответы бота, и обязал выплатить компенсацию. Бизнес, использующий ИИ, отвечает за его ответы.","teams":"Команды: напишите 5 правил использования ИИ в вашем проекте: проверка фактов, авторство, честность, приватность, ответственность.","takeaway":"Бизнес отвечает за то, что говорит его ИИ."}],"homework":"Возьми любой текст проекта, созданный с помощью ИИ, проверь в нём 3 факта, заполни протокол и добавь пометку об использовании ИИ.","support":"Список первоисточников по темам; шаблон протокола; готовый ответ ИИ с подсказками, где искать.","advanced":"Найти в ответе ИИ утверждение, которое нельзя проверить, и объяснить, как переписать его, чтобы оно стало проверяемым.","photo":{"src":"lessons/img/11_29.jpg","author":"Glenn Carstens-Peters","q":["Что вы видите на фото? Как это связано с нашей темой?","Какие правила работы с ИИ должны быть в школе и в бизнесе?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g11-l29.pptx","name":"29. Ответственная работа с ИИ — проверка фактов, авторство, этика (11 кл).pptx","mb":1.4}},{"id":"11_30","g":11,"l":30,"topic":"Итоговая работа за полугодие: все разделы","module":"Все разделы","format":"Итоговая работа","skills":["Критическое мышление","Принятие решений"],"goal":"К концу урока ученик сможет выполнить итоговую работу за полугодие: ответить на тест по всем разделам (маркетинг, ИИ, финансовая грамотность) и решить практическое задание с расчётами.","criteria":["Я правильно отвечаю на тестовые вопросы по разделам полугодия.","Я решаю практическое задание с полным ходом расчёта.","Я проверяю работу по чек-листу и честно оцениваю результат."],"result":"Выполненная итоговая работа: тест из 12 вопросов, практическое задание «Маркетинг и финансы проекта» и лист самопроверки.","stages":[{"stage":"Разминка «Найди пару»","min":4},{"stage":"Выполнение работы","min":28},{"stage":"Самопроверка","min":4},{"stage":"Рефлексия","min":4}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Маркетинг (marketing)","real":"Изучение клиентов и продвижение продукта","shown":"Изучение клиентов и продвижение продукта","truth":true,"first":"М"},{"term":"Повторение (review)","real":"Закрепление изученного перед проверкой","shown":"Индекс лояльности: % промоутеров минус % критиков","truth":false,"first":"П"},{"term":"Конверсия","real":"Доля совершивших целевое действие","shown":"Доля совершивших целевое действие","truth":true,"first":"К"},{"term":"CPA","real":"Стоимость привлечения одного клиента","shown":"Закрепление изученного перед проверкой","truth":false,"first":"C"},{"term":"ROMI","real":"Возврат маркетинговых инвестиций","shown":"Возврат маркетинговых инвестиций","truth":true,"first":"R"},{"term":"NPS","real":"Индекс лояльности: % промоутеров минус % критиков","shown":"Стоимость привлечения одного клиента","truth":false,"first":"N"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Маркетинг (marketing)","def":"Изучение клиентов и продвижение продукта"},{"term":"Повторение (review)","def":"Закрепление изученного перед проверкой"},{"term":"Конверсия","def":"Доля совершивших целевое действие"},{"term":"CPA","def":"Стоимость привлечения одного клиента"},{"term":"ROMI","def":"Возврат маркетинговых инвестиций"},{"term":"NPS","def":"Индекс лояльности: % промоутеров минус % критиков"},{"term":"Галлюцинация ИИ","def":"Уверенный, но неверный ответ модели"}],"english":"marketing — маркетинг; review — повторение","concepts":{"head":"Базовые понятия","items":["Маркетинг (marketing): охват, CTR = клики ÷ показы; конверсия = покупки ÷ клики; CPA = затраты ÷ покупатели; ROMI = (маржинальная прибыль − затраты) ÷ затраты × 100%; NPS = % промоутеров (9–10) − % критиков (0–6).","Личный бренд: ценности + сильные стороны + позиционирование.","ИИ: модель предсказывает токены; ошибки — устаревшие данные, мало данных, галлюцинации; промпт — роль, задача, контекст, формат; факты проверяем по первоисточникам.","Финансы: НДС 16% (в цене — × 16 ÷ 116), ИП на упрощёнке — 4% от дохода."]},"steps":{"head":"Как выполнять работу, по шагам","items":["Обзор всех заданий","Тест, сомнительные пометить","Практика — данные, формула, расчёт, ответ с единицами","Возврат к пометкам","Самопроверка"]},"scheme":"«карта полугодия»: «Маркетинг-аналитика», «Бюджет и ROMI», «Личный бренд», «Стратегия», «ИИ: устройство, промпты, сравнение, этика», «Ярмарка: упаковка и NPS».","examples":[{"lab":"Казахстанский","text":"Кампания бренда из Тараза — затраты 80 000 условных тенге, 40 покупок, маржа 3 000: CPA = 2 000, ROMI = (120 000 − 80 000) ÷ 80 000 = 50%."},{"lab":"Второй пример","text":"Из 20 оценок 10 промоутеров и 4 критика: NPS = 50 − 20 = 30."}],"mistake":{"myth":"Считать ROMI от выручки","fix":"Только от маржинальной прибыли."},"check":[{"q":"Чем ROMI отличается от выручки?","a":"Учитывает маржу и затраты"},{"q":"Почему ответ ИИ надо проверять?","a":"Галлюцинации, устаревшие данные"},{"q":"Какая формула NPS?","a":"% промоутеров − % критиков"}],"kz":{"text":"Технопарк Astana Hub и казахстанские IT-компании ищут молодых специалистов, умеющих работать с данными и ИИ. В начале урока тренер напоминает, что все расчёты ведутся в условных тенге, а налоговые цифры — по правилам 2026 года.","link":"итоговая работа проверяет именно эти навыки — считать эффективность и проверять ИИ."},"world":{"text":"Мировые компании всё чаще требуют от выпускников сочетания маркетинговой аналитики и грамотной работы с ИИ; Всемирный экономический форум в докладах «Future of Jobs» называет аналитическое мышление и работу с ИИ ключевыми навыками. Вопрос после работы: какие навыки этого полугодия вы покажете работодателю?","link":""},"fact":"Доклад Всемирного экономического форума «The Future of Jobs Report» выходит примерно раз в два года и называет навыки, которые будут наиболее востребованы; аналитическое мышление стабильно входит в верхнюю часть списка.","cards":[{"n":"1","title":"Тест (по 1 баллу)","lines":["1) CTR = а) клики ÷ показы; б) покупки ÷ клики.","2) CPA — это: а) затраты ÷ покупатели; б) выручка ÷ затраты.","3) ROMI считают от: а) выручки; б) маржинальной прибыли.","4) Промоутер в NPS ставит: а) 7–8; б) 9–10.","5) Охват — это: а) уникальные люди; б) все показы.","6) Позиционирование отвечает на вопрос: а) кому и чем мы полезны и чем отличаемся; б) сколько стоит логотип.","7) Языковая модель: а) ищет ответ в базе; б) предсказывает следующий токен.","8) Галлюцинация ИИ — это: а) уверенный неверный ответ; б) ошибка интернета.","9) Схема промпта: а) роль, задача, контекст, формат; б) цвет, шрифт, логотип.","10) Первоисточник для ставки налога: а) kgd.gov.kz; б) пост блогера.","11) НДС в цене 11 600 тенге: а) 1 600; б) 1 856.","12) Налог ИП на упрощёнке: а) 4% от дохода; б) 4% от прибыли."],"hand":"Сдать: бланк ответов.","answers":[["1","А"],["2","А"],["3","Б"],["4","Б"],["5","А"],["6","А"],["7","Б"],["8","А"],["9","А"],["10","А"],["11","А"],["12","А"]]},{"n":"2","title":"Практика (12 баллов)","lines":["Проект «Худи школы», цена 10 000, себестоимость 6 000.","Канал А: показы 50 000, клики 1 000, покупки 30, затраты 90 000.","Канал Б: показы 20 000, клики 600, покупки 30, затраты 60 000.","1) CTR, конверсия, CPA для каждого канала.","2) ROMI каждого канала. (А: (120 000 − 90 000) ÷ 90 000 ≈ 33%; Б: (120 000 − 60 000) ÷ 60 000 = 100%.)","3) Налог ИП 4% с выручки 600 000.","4) NPS: из 25 оценок 13 промоутеров, 7 нейтральных, 5 критиков."],"hand":"Сдать: решения.","answers":[["1","А: 2%, 3%, 3 000; Б: 3%, 5%, 2 000."],["3","24 000."],["4","52% − 20% = 32."]]},{"n":"3","title":"Чек-лист","lines":["Все 12 ответов.","В практике формулы.","ROMI от маржи.","Единицы (%, тенге).","Ответы правдоподобны."],"hand":"Сдать: вместе с работой.","answers":[]}],"homework":"Запиши 2 темы полугодия, в которых уверен, и 1 тему для разбора на следующем уроке с конкретным вопросом.","support":"Справочная строка с формулами (без ответов); дополнительные 3 минуты при необходимости.","advanced":"Дополнительное задание: при каком CPA кампания из практики выйдет на ROMI 0%? (CPA = маржа единицы = 4 000 тенге.)","photo":{"src":"lessons/img/11_30.jpg","author":"Vitaly Gariev","q":["Что вы видите на фото? Как это связано с нашей темой?","Какие навыки этого полугодия вы покажете работодателю?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g11-l30.pptx","name":"30. Итоговая работа за полугодие — все разделы (11 кл).pptx","mb":1.5}},{"id":"11_31","g":11,"l":31,"topic":"Работа над ошибками и обратная связь по итоговой работе","module":"Все разделы","format":"Итоговая работа","skills":["Критическое мышление"],"goal":"К концу урока ученик сможет классифицировать свои ошибки в итоговой работе, исправить их с объяснением правила и составить план устранения пробелов по обратной связи тренера.","criteria":["Я нахожу и классифицирую свои ошибки.","Я исправляю каждую с объяснением правила своими словами.","Я превращаю обратную связь тренера в конкретный план."],"result":"Лист работы над ошибками: таблица «ошибка — тип — исправление — правило», решённые задачи на закрепление и личный план из 2 шагов.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":4},{"stage":"Выполнение работы","min":28},{"stage":"Самопроверка","min":4},{"stage":"Рефлексия","min":4}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Ошибка (mistake)","real":"Неверный шаг или ответ, показывающий, что доучить","shown":"Неверный шаг или ответ, показывающий, что доучить","truth":true,"first":"О"},{"term":"Обратная связь (feedback)","real":"Конкретный комментарий: что хорошо и что улучшить","shown":"Шаги, чтобы тема перестала вызывать ошибки","truth":false,"first":"О"},{"term":"Вычислительная ошибка","real":"Верный метод, неверная арифметика","shown":"Верный метод, неверная арифметика","truth":true,"first":"В"},{"term":"Понятийная ошибка","real":"Неверное понимание правила или термина","shown":"Конкретный комментарий: что хорошо и что улучшить","truth":false,"first":"П"},{"term":"Ошибка чтения условия","real":"Пропущенные данные или неверно понятый вопрос","shown":"Пропущенные данные или неверно понятый вопрос","truth":true,"first":"О"},{"term":"План устранения пробелов","real":"Шаги, чтобы тема перестала вызывать ошибки","shown":"Неверное понимание правила или термина","truth":false,"first":"П"}],"perm":[3,2,1,0,5,4]},"glossary":[{"term":"Ошибка (mistake)","def":"Неверный шаг или ответ, показывающий, что доучить"},{"term":"Обратная связь (feedback)","def":"Конкретный комментарий: что хорошо и что улучшить"},{"term":"Вычислительная ошибка","def":"Верный метод, неверная арифметика"},{"term":"Понятийная ошибка","def":"Неверное понимание правила или термина"},{"term":"Ошибка чтения условия","def":"Пропущенные данные или неверно понятый вопрос"},{"term":"План устранения пробелов","def":"Шаги, чтобы тема перестала вызывать ошибки"}],"english":"mistake — ошибка; feedback — обратная связь","concepts":{"head":"Определения","items":["Ошибка (mistake) — данные для улучшения, как неудачная рекламная кампания для маркетолога.","Обратная связь (feedback) показывает, что изменить.","Типы ошибок: вычислительные, понятийные, чтения условия."]},"steps":{"head":"Как работать, по шагам","items":["Найти задания с потерянными баллами","Определить тип","Найти правило в конспекте","Решить заново с полным ходом","Правило своими словами","Похожая задача","План из 2 шагов"]},"scheme":"Три корзины «Считаю», «Понимаю», «Читаю»; стикеры с ошибками класса показывают, что повторить вместе.","examples":[{"lab":"Казахстанский","text":"Ученик посчитал ROMI канала А как (30 × 10 000 − 90 000) ÷ 90 000 = 233% — от выручки, а не от маржи. Понятийная ошибка; правильно (30 × 4 000 − 90 000) ÷ 90 000 ≈ 33%."},{"lab":"Второй пример","text":"В NPS ученик вычел из промоутеров нейтральных (52% − 28%) — ошибка правила: вычитаются только критики, правильно 32."}],"mistake":{"myth":"Переписать правильный ответ без объяснения","fix":"Без правила ошибка вернётся."},"check":[{"q":"Какая ошибка повторится чаще, если её не исправить?","a":"Понятийная"},{"q":"Почему нужно решать похожую задачу?","a":"Чтобы закрепить правило"},{"q":"Как превратить обратную связь в план?","a":"Назвать конкретное действие и срок"}],"kz":{"text":"Казахстанские IT-компании и стартапы технопарка Astana Hub выпускают продукты итерациями: версия, отзывы, исправления, новая версия.","link":"работа над ошибками — итерация знаний."},"world":{"text":"В технологических компаниях мира принят формат «разбор без поиска виноватых» (blameless postmortem): после сбоя команда разбирает причины, а не наказывает людей, чтобы ошибка не повторилась.","link":""},"fact":"Стикеры Post-it появились благодаря «неудачному» слабому клею, который в 1968 году изобрёл учёный компании 3M Спенсер Сильвер; применение ему нашёл коллега Арт Фрай, и продукт вышел в 1980 году.","cards":[{"n":"1","title":"Работа над ошибками","lines":["Таблица: № задания | Мой ответ | Тип (считаю / понимаю / читаю) | Правильное решение | Правило своими словами.","Внизу: «Мой план: 1) … 2) …»."],"hand":"Сдать: заполненную таблицу.","answers":[]},{"n":"2","title":"Задачи на закрепление","lines":["1) Показы 40 000, клики 800, покупки 32. CTR и конверсия?","2) Затраты 64 000, покупок 32. CPA?","3) Маржа 3 500, покупок 32, затраты 64 000. ROMI? ((112 000 − 64 000) ÷ 64 000 = 75%.)","4) 30 оценок: 15 промоутеров, 9 нейтральных, 6 критиков. NPS?","5) Перепишите промпт «сделай рекламу» по схеме РЗКФ."],"hand":"Сдать: решения.","answers":[["1","2%; 4%."],["2","2 000."],["4","50% − 20% = 30."]]}],"homework":"Выполни свой план: реши 2 задачи по теме с ошибкой и запиши правило своими словами.","support":"Образец заполненной строки; карточки-подсказки с формулами; консультант-одноклассник.","advanced":"Составить задачу «с ловушкой» по типичной ошибке класса с ответом и объяснением.","photo":{"src":"lessons/img/11_31.jpg","author":"lilartsy","q":["Что вы видите на фото? Как это связано с нашей темой?","Как такой подход помогает учиться на ошибках?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g11-l31.pptx","name":"31. Работа над ошибками и обратная связь по итоговой работе (11 кл).pptx","mb":1.4}},{"id":"11_32","g":11,"l":32,"topic":"Игра-повторение по темам полугодия","module":"Все разделы","format":"Деловая игра","skills":["Командная работа","Лидерство","Критическое мышление"],"goal":"К концу урока ученик сможет применить понятия полугодия (маркетинговая аналитика, бюджет, бренд, ИИ) в командной игре и объяснить решения с опорой на расчёты.","criteria":["Я правильно решаю задачи раундов и проверяю решения команды.","Я выполняю свою роль и участвую в общих решениях.","Я называю тему, которую закрепил, и что ещё повторить."],"result":"Командный отчёт игры «Маркетинговое агентство»: решения двух раундов, расчёты показателей, итоговый счёт и разбор ошибок.","stages":[{"stage":"Разминка «Угадай слово»","min":4},{"stage":"Инструктаж","min":4},{"stage":"Раунд 1","min":10},{"stage":"Раунд 2","min":10},{"stage":"Разбор","min":8},{"stage":"Рефлексия","min":4}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Повторение (review)","real":"Закрепление изученного через применение","shown":"Закрепление изученного через применение","truth":true,"first":"П"},{"term":"Игра (game)","real":"Учебная модель с правилами, ролями и результатом","shown":"Возврат маркетинговых инвестиций","truth":false,"first":"И"},{"term":"Агентство","real":"Компания, которая ведёт маркетинг для клиентов","shown":"Компания, которая ведёт маркетинг для клиентов","truth":true,"first":"А"},{"term":"Бриф","real":"Задание клиента агентству: цель, аудитория, бюджет","shown":"Учебная модель с правилами, ролями и результатом","truth":false,"first":"Б"},{"term":"CPA","real":"Стоимость привлечения клиента","shown":"Стоимость привлечения клиента","truth":true,"first":"C"},{"term":"ROMI","real":"Возврат маркетинговых инвестиций","shown":"Задание клиента агентству: цель, аудитория, бюджет","truth":false,"first":"R"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Повторение (review)","def":"Закрепление изученного через применение"},{"term":"Игра (game)","def":"Учебная модель с правилами, ролями и результатом"},{"term":"Агентство","def":"Компания, которая ведёт маркетинг для клиентов"},{"term":"Бриф","def":"Задание клиента агентству: цель, аудитория, бюджет"},{"term":"CPA","def":"Стоимость привлечения клиента"},{"term":"ROMI","def":"Возврат маркетинговых инвестиций"},{"term":"Фактчекинг","def":"Проверка фактов по источникам"}],"english":"review — повторение; game — игра","concepts":{"head":"Определения","items":["Игра (game) «Маркетинговое агентство» — повторение (review) полугодия: команды — агентства, получающие брифы от клиентов.","Цель — набрать больше баллов за верные расчёты и сильные решения."]},"steps":{"head":"Как играть, по шагам","items":["Роли — аккаунт-менеджер (капитан), аналитик, креативщик, ИИ-специалист","Раунд 1 — «аналитика»: 5 задач (CTR, конверсия, CPA, ROMI, NPS), +10 баллов за верный ответ","Раунд 2 — «бриф»: команда получает бриф и события (ИИ выдал ошибку, бюджет урезан, плохие отзывы), за 10 минут готовит решение: канал, бюджет, слоган, проверка фактов","Разбор"]},"scheme":"Табло агентств «раунд 1 — раунд 2 — бонусы — итог» и «карта тем»: аналитика, бюджет и ROMI, бренд и упаковка, стратегия, промпты, фактчекинг, NPS.","examples":[{"lab":"Казахстанский","text":"Бриф «Кофейня у колледжа в Таразе, бюджет 100 000 условных тенге, цель 50 новых клиентов». Если CPA соцсети 2 500, а листовок — 1 500 (но не более 30 клиентов), лучшая комбинация: 30 через листовки (45 000) и 22 через соцсеть (55 000) = 52 клиента."},{"lab":"Второй пример","text":"Событие «ИИ написал в посте, что кофейня работает с 1990 года, хотя она открылась в 2024 году» — команда, проверившая факт, получает бонус."}],"mistake":{"myth":"Тратить весь бюджет в один «модный» канал","fix":"Разбираем пример кофейни."},"check":[{"q":"Как выбрать канал при ограниченном бюджете?","a":"По CPA и ограничениям канала"},{"q":"Что сделать с фактом от ИИ?","a":"Проверить по первоисточнику"},{"q":"Как реагировать на плохие отзывы?","a":"Найти причину и решение"}],"kz":{"text":"Казахская национальная игра тоғызқұмалақ требует счёта и стратегического планирования на несколько ходов вперёд. В начале урока тренер упоминает тогыз кумалак как традицию стратегического мышления.","link":"в маркетинговой игре тоже нужно просчитывать последствия решений."},"world":{"text":"Крупнейшие рекламные холдинги мира работают как сети агентств в десятках стран, адаптируя глобальные кампании к местной культуре.","link":""},"fact":"Термин «бриф» пришёл в рекламу из английского brief — «краткий»: первые рекламные агентства, такие как основанное в 1869 году в США N. W. Ayer & Son, работали по кратким заданиям клиентов. N. W. Ayer считается одним из первых рекламных агентств в современном смысле.","cards":[{"n":"1","title":"Правила «Маркетингового агентства»","lines":["Роли: аккаунт-менеджер, аналитик, креативщик, ИИ-специалист.","Раунд 1: +10 баллов за верный ответ.","Раунд 2: до 30 баллов за решение брифа. Бонусы: +5 за найденную ошибку ИИ, +5 за «помощь соседу» (один раз)."],"hand":"Сдать: не нужно.","answers":[]},{"n":"2","title":"Раунд 1","lines":["1) Показы 30 000, клики 900. CTR?","2) Клики 900, покупки 45. Конверсия?","3) Затраты 90 000, покупки 45. CPA?","4) Маржа 3 000, покупки 45, затраты 90 000. ROMI?","5) 40 оценок: 22 промоутера, 10 нейтральных, 8 критиков. NPS?"],"hand":"Сдать: ответы.","answers":[["1","3%."],["2","5%."],["3","2 000."],["4","50%."],["5","55% − 20% = 35."]]},{"n":"3","title":"Бриф и события","lines":["Бриф: «Кофейня у колледжа, бюджет 100 000 условных тенге, цель — 50 новых клиентов, маржа с клиента 3 000». Каналы: соцсеть CPA 2 500; листовки CPA 1 500 (не более 30 клиентов); блогер CPA 4 000.","Событие 1: ИИ написал в посте «работаем с 1990 года», а кофейня открыта в 2024 году — исправьте.","Событие 2: бюджет урезали до 80 000 — пересчитайте.","Событие 3: отзывы «долго ждать» — предложите ответ бренда."],"hand":"Сдать: решение: каналы, бюджет, число клиентов, ROMI, слоган, исправления.","answers":[["Тренеру","100 000 — 30 листовками (45 000) + 22 соцсетью (55 000) = 52 клиента, ROMI = (156 000 − 100 000) ÷ 100 000 = 56%; при 80 000 — 30 + 14 = 44 клиента."]]}],"practice":[{"type":"case","title":"Угадай: принцип личного бренда","minutes":6,"source":"Повторение: личный бренд","hook":"Блогер 3 года пишет только о финансах для подростков, в одном стиле. Какой принцип?","story":["Темы — только финансы для подростков.","Одинаковый стиль оформления и тон.","Регулярные посты по расписанию."],"question":"Какой принцип личного бренда здесь главный?","options":["Много тем сразу","Скандальность","Постоянство и фокус","Случайность"],"answerIndex":2,"reveal":"Постоянство и фокус делают бренд узнаваемым. Аудитория знает, чего ждать.","teams":"Команды: назовите ещё 2 принципа личного бренда с примерами.","takeaway":"Фокус + постоянство = узнаваемость."},{"type":"case","title":"Угадай: ответственный ИИ","minutes":6,"source":"Повторение: ответственная работа с ИИ","hook":"ИИ написал реферат. Ученик сдал его под своим именем без проверки. Что нарушено?","story":["Текст полностью создан ИИ.","Факты не проверены.","Учитель не знает, что использовался ИИ."],"question":"Что нарушено?","options":["Ничего","Только сроки","Только оформление","Честность авторства и проверка фактов"],"answerIndex":3,"reveal":"Использовать ИИ можно, но честно: указать, как помогал ИИ, проверить факты и добавить свою мысль.","teams":"Команды: сформулируйте правило «как честно использовать ИИ в школьном проекте».","takeaway":"ИИ — помощник, автор — ты."}],"homework":"Составь 3 вопроса викторины по темам, где ошибался в итоговой работе, с ответами и объяснениями.","support":"Памятка с формулами у каждого агентства; помощник у аналитика.","advanced":"Роль «стратега»: предложить решение брифа с ROMI выше 50% и доказать расчётом.","photo":{"src":"lessons/img/11_32.jpg","author":"National Cancer Institute","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему кампанию, успешную в одной стране, нужно менять для Казахстана?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g11-l32.pptx","name":"32. Игра-повторение по темам полугодия (11 кл).pptx","mb":1.5}}];
